/** Original illustrative Task 2 responses, authored for the October expansion.
 * They are study references, not official scripts or a promised IELTS score. */
export interface WritingEssayPack {
  key: string;
  title: string;
  topic: string;
  family: string;
  prompt: string;
  model: string;
  keyPoints: string[];
}

type Plan = [string, string, string, string, string, string, string, string, string];

// Every introduction, argument, example, qualification and conclusion is topic-specific.
// No stock argumentative paragraphs or model sentences are added by this formatter.
function build(family: string, plan: Plan, _index: number): WritingEssayPack {
  const [key, title, topic, prompt, opening, position, argumentOne, argumentTwo, judgement] = plan;
  const detail = essayDetails[key];
  if (!detail) throw new Error(`Missing original Task 2 development for ${key}`);
  const paragraphs = [
    `${opening} ${position}`,
    argumentOne,
    argumentTwo,
    detail,
    `In conclusion, ${judgement}`,
  ];
  return {
    key: `triple-task2-${key}`,
    title,
    topic,
    family,
    prompt,
    model: paragraphs.join('\n\n'),
    keyPoints: [position, argumentOne, argumentTwo, judgement],
  };
}

const opinion: Plan[] = [
  ['school-breakfast', 'Breakfast as a school responsibility', 'Education and health', 'Governments should provide a free breakfast to every schoolchild. To what extent do you agree or disagree?', 'A meal before lessons can influence whether children arrive ready to learn.', 'I largely agree with universal school breakfasts, provided that food quality and voluntary participation are protected.', 'Hunger makes sustained attention harder, even for pupils who understand the lesson. In a school serving households with irregular working hours, a breakfast club gives children a predictable start without requiring teachers to identify whose family is struggling. Universal access also avoids a separate queue that could expose poorer pupils to embarrassment and discourage them from eating.', 'There are nevertheless costs beyond buying food. Schools need safe storage, trained staff and options for allergies, and an early meal cannot compensate for unhealthy lunches. A workable scheme could begin in schools where morning hunger is common, then expand with proper kitchen funding. Families should remain free to feed children at home rather than treating attendance as compulsory.', 'free provision is justified as educational support, but an inclusive meal and adequate facilities matter more than simply announcing that breakfast is available.'],
  ['repair-label', 'A right to repair household devices', 'Technology and consumption', 'Manufacturers should be required to publish instructions that allow people to repair their own electronic devices. To what extent do you agree or disagree?', 'Many household electronics are discarded because a minor fault cannot be repaired affordably.', 'I support a legal right to repair, with sensible exceptions for procedures that pose serious safety risks.', 'Repair information would make independent workshops a realistic alternative to replacing an entire device. A washing machine with a worn switch could remain useful for years if a technician could obtain a diagram and a reasonably priced spare part. More competition would also reduce the advantage enjoyed by a manufacturer that currently controls both the product and every authorised repair.', 'Publishing every technical detail without explanation could expose inexperienced owners to danger. A rechargeable battery, for example, may catch fire if handled incorrectly, so instructions must distinguish ordinary maintenance from work requiring specialist training. Manufacturers could provide diagnostic guides and parts catalogues while clearly restricting hazardous procedures. This is a narrower and more defensible exception than withholding all information to protect sales.', 'repair instructions should normally be public because they extend product life and consumer choice, while explicit safety boundaries can address the strongest objection.'],
  ['car-free-school', 'Restricting cars beside schools', 'Transport and cities', 'Private cars should be banned from streets directly outside schools during arrival and departure times. To what extent do you agree or disagree?', 'The short school run often creates the busiest traffic conditions at the most vulnerable place.', 'I favour timed street closures near school entrances, alongside accessible drop off arrangements for those who genuinely need them.', 'Reducing moving cars immediately outside a school lowers conflict between drivers and children crossing the road. It also removes the crowd of vehicles that can block a young pedestrian from view. A supervised walking route from a nearby public car park would allow families living farther away to participate without requiring every journey to be completed on foot.', 'A blanket restriction without alternatives would unfairly affect children with mobility difficulties or parents travelling directly to distant workplaces. Exemptions for adapted vehicles and an accessible stopping point should therefore be planned before closures begin. Local residents also need clear entry rules. Trials using removable barriers can reveal whether traffic simply shifts to another dangerous junction and requires a wider solution.', 'timed closures are worthwhile, but they should form part of an accessible school travel plan rather than transferring risk and inconvenience to neighbouring streets.'],
  ['public-library-evening', 'Keeping libraries open after work', 'Public services', 'Public libraries should remain open every evening, even if this means buying fewer new books. To what extent do you agree or disagree?', 'A public library has limited value to someone who is working whenever its doors are open.', 'I agree that some evening access deserves priority, but not that every branch must sacrifice its collection to provide it.', 'Later opening gives shift workers and students a quiet place to read, use computers and complete applications. For a tenant sharing a crowded flat, an evening study desk may be more valuable than another copy of a popular novel. Library usefulness depends on when people can reach its resources, so attendance patterns should influence spending rather than treating daytime hours as the default.', 'However, extended access to outdated information can undermine the same educational purpose. A branch that stops replacing examination guides or damaged children’s books would eventually become less useful. Neighbouring libraries could alternate their evening schedules and share reservations, preserving access without paying for every building to remain open daily. Transport links and local demand should determine which branches take that role.', 'a coordinated evening service is preferable to either an inflexible daytime timetable or a universal opening requirement that gradually weakens the book collection.'],
  ['food-marketing-child', 'Advertising snacks to children', 'Health and media', 'Advertising foods high in sugar to children should be prohibited. To what extent do you agree or disagree?', 'Children encounter food promotions long before they can judge a persuasive commercial message.', 'I support restrictions on marketing sugary products to young children, while recognising that advertising rules alone cannot improve their diets.', 'Young viewers often interpret a cheerful character or game reward as evidence that a snack is desirable. Repeated requests then place pressure on parents, including those who cannot afford healthier alternatives. Removing product placement from children’s programmes and paid promotions in games would reduce a commercial influence that children are poorly equipped to question, without prohibiting adults from buying the products.', 'A ban must cover digital channels or brands will simply move their campaigns away from television. Equally, schools need affordable nutritious food and families need clear labelling, otherwise reducing advertisements leaves the underlying choices unchanged. Rules should define the nutritional threshold and intended audience precisely, allowing genuine cooking education while preventing a sweet manufacturer from disguising a sales campaign as a lesson.', 'a carefully defined advertising prohibition is justified by children’s vulnerability, and it should complement measures that make healthier everyday choices practical.'],
  ['work-email-hours', 'Disconnecting after working hours', 'Employment', 'Employers should be forbidden from requiring workers to answer messages outside contracted working hours. To what extent do you agree or disagree?', 'Digital communication can turn a fixed working day into an expectation of continuous availability.', 'I agree with a right to disconnect, provided that genuinely necessary emergency duties are separately agreed and compensated.', 'An ordinary message may look harmless, but repeated evening requests make employees plan family time around possible interruptions. A worker caring for a child cannot properly rest if a supervisor expects immediate answers. Clear response windows would encourage managers to schedule tasks realistically and would prevent ambitious colleagues from creating an informal standard of unpaid availability for everybody else.', 'Some services cannot stop at a convenient hour. A network engineer may need to respond to a major outage, while a hospital requires reliable emergency cover. These cases support organised on call arrangements rather than unlimited access to every worker. Contracts should state who is available, how often that responsibility rotates, and what additional pay or time off follows an interruption.', 'routine work should respect contracted hours, whereas essential exceptions require transparent arrangements so that emergency cover does not become an excuse for permanent unpaid labour.'],
  ['river-personhood', 'Stronger protection for urban rivers', 'Environment and law', 'City governments should give river protection priority over new commercial development along riverbanks. To what extent do you agree or disagree?', 'Riverbanks are attractive places for development, yet construction can damage functions that a city cannot easily replace.', 'I agree that protection should normally take priority, although carefully designed development outside sensitive areas can remain possible.', 'A healthy river corridor absorbs rainfall and provides space for floodwater. Replacing vegetation with a continuous row of buildings may increase future drainage costs far beyond the initial sale of land. A city could retain wetlands and public paths while locating shops on already developed plots nearby. This preserves the environmental service instead of relying entirely on concrete barriers later.', 'Commercial projects can provide employment and help fund neglected waterfront improvements. Rejecting all investment would therefore be unnecessary if strict setback distances, wastewater standards and ecological assessments are enforced. The difficulty is that private developers receive immediate profits while flood damage is shared by residents. Independent assessment is essential to prevent promised landscaping from being mistaken for protection of the actual river system.', 'environmental safeguards should set the boundary within which riverside business develops, because temporary commercial gains do not justify irreversible damage to a city’s natural infrastructure.'],
  ['student-councils-budget', 'Giving pupils control over a school budget', 'Education and citizenship', 'Secondary school students should decide how part of their school budget is spent. To what extent do you agree or disagree?', 'Schools teach citizenship more convincingly when pupils experience the consequences of a real decision.', 'I support a limited student controlled budget, while essential staffing and safety expenditure should remain the responsibility of adults.', 'Choosing between library seating, sports equipment and a garden forces pupils to weigh competing interests. They must explain costs and persuade students outside their own friendship group, which makes participation more substantial than a council that can only offer suggestions. A modest annual fund could develop financial judgement while producing improvements that staff had not recognised as important to everyday school life.', 'Students may favour a highly visible purchase over maintenance or overlook those whose needs are less popular. Staff guidance and an inclusive voting process are therefore necessary. Proposals could be required to include expected running costs and an accessibility check before a final vote. The fund should be large enough to matter but separate from money needed for qualified teachers or building repairs.', 'real but bounded financial responsibility can teach democratic decision making effectively, as long as adult oversight protects essential services and pupils who are easily overlooked.'],
  ['holiday-flight-tax', 'Charging more for frequent leisure flights', 'Environment and travel', 'People who take several leisure flights each year should pay a higher air travel tax than occasional travellers. To what extent do you agree or disagree?', 'The environmental impact of flying is unevenly distributed among travellers.', 'I agree with a rising tax on frequent leisure flights, if necessary journeys and practical administration are addressed fairly.', 'A charge that increases after the first annual leisure trip targets repeated discretionary travel more directly than a flat ticket tax. Someone taking several weekend flights has more room to change behaviour than a family making one rare visit abroad. Revenue could improve international rail connections, creating alternatives rather than relying entirely on a penalty to persuade people to stay home.', 'Determining the purpose of a journey is not always simple. Visiting a sick relative may look like a holiday in booking records, and residents of remote islands have fewer alternatives. A workable system would allow documented exemptions and count journeys consistently across airlines, while protecting passenger information. Without these safeguards, the tax could reward people who split bookings or punish those with unavoidable travel needs.', 'frequent discretionary flying should face a greater environmental charge, but transparent exemptions and investment in alternatives are necessary for the measure to be both effective and fair.'],
  ['museum-return', 'Returning cultural objects', 'Culture and history', 'Museums should return cultural objects to the communities from which they were taken without permission. To what extent do you agree or disagree?', 'An object can be both a museum exhibit and a living part of another community’s heritage.', 'I agree that clearly documented, non consensual removal creates a strong case for return rather than permanent retention.', 'Possession in a respected museum does not erase the circumstances of acquisition. A ceremonial object taken during a military occupation may still hold religious significance for descendants, so its removal represents more than a loss of tourism revenue. Returning it can restore local access and allow the originating community to decide how, or whether, the object should be displayed.', 'There are difficult cases involving disputed ownership and conservation facilities. These issues justify careful research and cooperation, not an automatic refusal based on the wealth of the current museum. Shared conservation training or a gradual transfer could protect fragile objects. Where several communities claim the same item, independent mediation may be needed before relocation, with the evidence and reasoning made public.', 'objects acquired without meaningful consent should generally be returned, while genuine uncertainty should be resolved through transparent cooperation rather than using technical difficulties to postpone justice indefinitely.'],
  ['rental-pets', 'Allowing pets in rented homes', 'Housing and community', 'Landlords should not be allowed to impose a complete ban on pets in rented homes. To what extent do you agree or disagree?', 'A rented home is also the place where tenants build their personal and family lives.', 'I broadly agree that blanket pet bans are unreasonable, although proportionate restrictions can be justified by the property and the animal involved.', 'A universal ban forces a responsible owner to surrender an animal or accept unsuitable housing, even when no damage has occurred. Long term tenants may reasonably regard a quiet cat as part of their household. Requiring landlords to consider individual applications would distinguish manageable risks from assumptions and would reduce the artificial shortage of homes available to people with pets.', 'Neighbours and property owners also have legitimate interests. A large dog in a tiny shared flat may create welfare problems, while repeated noise can disturb other tenants. Clear rules on supervision, cleaning and repair responsibility would be more precise than automatic permission for every animal. Any additional deposit should reflect lawful, evidenced costs and should not become a disguised method of excluding all owners.', 'individual assessment is preferable to a blanket ban because it respects tenants’ lives while allowing demonstrable damage, noise and animal welfare concerns to be addressed.'],
  ['sports-equal-prize', 'Equal prizes in publicly funded sport', 'Sport and equality', 'Sports competitions receiving public money should offer equal prize money to male and female winners. To what extent do you agree or disagree?', 'Public funding changes the responsibilities of a sporting organiser because the money comes from the wider community.', 'I agree with equal winner prizes in comparable events that receive public support, even if their current commercial revenues differ.', 'Prize policy signals which achievements a society values. When athletes complete equivalent competitions under the same organiser, paying women less can reinforce a cycle in which fewer girls see sport as a viable career. Public money is already intended to provide social benefits beyond ticket sales, so it can reasonably support fair recognition rather than reproduce every inequality of the existing market.', 'Commercial sponsors may argue that audience size should determine payments. That is more relevant to privately negotiated advertising income than to a prize partly financed by taxpayers. Organisers should still compare equivalent competition formats and publish the cost of the policy. Equal prizes do not by themselves solve unequal training facilities, media coverage or safety, so those areas also require attention.', 'equal prizes are an appropriate condition of public support for comparable events, while broader investment is needed to make the opportunity to compete equally meaningful.'],
  ['local-food-schools', 'Local food in school kitchens', 'Agriculture and education', 'Schools should buy most of their food from local farmers, even when imported alternatives are cheaper. To what extent do you agree or disagree?', 'School food purchasing links children’s daily meals to the wider agricultural economy.', 'I support a strong preference for local suppliers, but not a rigid requirement that undermines affordability or nutritional variety.', 'Reliable school contracts can help nearby farmers plan production and can shorten the journey from harvest to lunch. Seasonal vegetables may also give pupils a practical connection to food education, especially if farms organise supervised visits. A purchasing scheme that includes several small growers would spread benefits and reduce dependence on one distant supplier whose transport delays could interrupt meal provision.', 'Local production is not automatically environmentally superior or sufficient throughout the year. A heated greenhouse may use more energy than transporting produce from a suitable climate, and some nutrients require foods unavailable locally. Budgets should therefore compare total costs, seasonality and quality. Flexible contracts could prioritise nearby staples while permitting imports that keep meals affordable and balanced during shortages.', 'local sourcing deserves encouragement, but nutritional standards and evidence about cost and environmental impact should determine the exceptions rather than geography becoming the only purchasing rule.'],
  ['voting-sixteen', 'Voting before adulthood', 'Society and citizenship', 'The voting age should be reduced to sixteen. To what extent do you agree or disagree?', 'Young people live with the long term consequences of decisions they are currently unable to influence directly.', 'I support voting at sixteen if schools provide impartial civic education and registration is easy to complete.', 'Policies on climate, education and public debt can shape a teenager’s entire adult life. Giving older pupils a vote recognises that stake and creates an incentive for politicians to explain their programmes to them. Voting while still at school could also establish a habit, since practical lessons can show how to register and compare evidence without endorsing a party.', 'Critics worry that teenagers lack experience and may follow parents or social media influencers. However, dependence and misinformation are not confined to one age group, and many adults vote with limited policy knowledge. The answer is stronger education about institutions, sources and disagreement, rather than assuming maturity appears on a particular birthday. Secret ballots and neutral school procedures would help protect individual choice.', 'sixteen year olds should be included because they have a legitimate stake in public decisions, with impartial education providing a better safeguard than exclusion alone.'],
  ['city-night-buses', 'Subsidising buses through the night', 'Transport and work', 'Large cities should subsidise bus services throughout the night. To what extent do you agree or disagree?', 'A city’s economy does not close when its daytime transport timetable ends.', 'I agree with a basic overnight bus network where demand exists, rather than expecting every route to operate continuously.', 'Hospital cleaners, restaurant staff and care workers often finish after the last ordinary bus. Without affordable transport, they may spend a substantial part of modest wages on taxis or walk along unsafe roads. Reliable overnight routes connecting major workplaces and housing districts would widen access to jobs and distribute the benefits of a city’s evening economy more fairly.', 'Running nearly empty buses on every suburban route would waste fuel and public money. A smaller network, coordinated transfer points and demand responsive services could provide essential coverage at lower cost. Authorities should consult shift workers rather than measuring need only through existing passenger numbers, since people unable to travel are absent from those statistics. Good lighting and trained staff would also affect whether passengers feel able to use it.', 'targeted night services merit subsidy because they support necessary work and safe travel, while route design should reflect real need rather than copy the entire daytime network.'],
  ['university-recorded-lectures', 'Recording university lectures', 'Education and technology', 'Universities should make recordings of all lectures available to their students. To what extent do you agree or disagree?', 'A lecture can be difficult to follow when illness, disability or unfamiliar terminology interferes with learning.', 'I support routine lecture recordings, with narrow exceptions for confidential material and interactive sessions that cannot reasonably be captured.', 'Recordings allow students to revisit a complex explanation at a useful pace. A learner studying in a second language can pause to understand a technical term rather than missing the rest of the argument. They also reduce the academic penalty of a brief illness. These benefits make recordings a supplement to attendance, especially when classroom time includes questions that a video cannot replace.', 'There are legitimate concerns about privacy and reduced participation. A lecturer discussing a patient case must protect sensitive information, and a student may hesitate to ask a personal question on camera. Recording the main presentation separately from the discussion can address both concerns. Courses should still require appropriate seminars and practical work, because access to a video does not demonstrate that a student has understood it.', 'recordings should be the normal arrangement because they improve access and revision, while confidentiality and active learning need thoughtful procedures rather than an unrestricted recording rule.'],
  ['fast-fashion-responsibility', 'Clothing companies and textile waste', 'Consumption and environment', 'Clothing companies should be legally responsible for collecting and recycling the garments they sell. To what extent do you agree or disagree?', 'Cheap clothing can leave disposal costs with households and councils long after the retailer has earned its profit.', 'I support producer responsibility for textile waste, provided that the policy prioritises durability and reuse ahead of recycling claims.', 'A collection obligation gives brands a reason to consider what happens to a garment after purchase. If mixed fibres are costly to process, a company may choose simpler materials or sturdier designs. Funding genuine repair and resale would extend useful life, whereas leaving all waste costs to local authorities allows high volume sellers to benefit without paying for the consequences of frequent replacement.', 'Collection alone can become a marketing exercise if donated clothing is shipped to places unable to handle it. Regulators should require evidence of where items go and how much material is actually reused. Consumers also retain responsibility to buy and care for clothing sensibly. A levy linked to durability and repairability would be harder to evade than a promotional collection bin with no reporting requirements.', 'companies should share responsibility for their products after sale, but transparent reuse and waste reduction targets are more valuable than a system that rewards collecting ever larger piles of unwanted clothing.'],
  ['remote-work-rural', 'Remote work and rural investment', 'Work and regional development', 'Governments should encourage remote workers to move to rural areas by offering grants. To what extent do you agree or disagree?', 'Remote employment makes residence less dependent on proximity to a city office.', 'I agree with limited relocation support only where it accompanies investment benefiting existing rural residents.', 'Additional residents can help sustain a village shop, school or bus route that has been losing customers. A remote worker brings outside income without requiring a new local factory, and demand for repairs or childcare may create employment. However, grants should favour towns with vacant homes and adequate services rather than attractive destinations where housing is already scarce.', 'Subsidies can also raise rents while doing little for poorer residents who cannot work online. If reliable broadband is missing, subsidised newcomers may leave after collecting the payment. Governments would achieve a fairer outcome by improving connectivity, healthcare and transport first, with relocation payments tied to genuine residence. Community consultation can reveal whether the local priority is new residents or better support for those already there.', 'rural relocation grants can help selected communities, but shared infrastructure and protection against housing pressure must take priority over rewarding people simply for changing their address.'],
  ['public-art-maintenance', 'Maintenance before new public art', 'Culture and public spending', 'Local councils should maintain existing public artworks before commissioning new ones. To what extent do you agree or disagree?', 'A neglected sculpture can turn a cultural investment into an eyesore or even a safety hazard.', 'I largely agree that maintenance should come first, while allowing new work when the existing collection has a secure care plan.', 'The value of an artwork depends on whether people can continue to experience it. Corrosion, broken lighting or an inaccessible setting can erase that benefit, even if the original purchase was celebrated. Ring fenced maintenance funds would protect earlier spending and demonstrate respect for the artist’s work. Repairs can also involve local apprentices, creating skills rather than repeatedly paying for prominent openings.', 'An absolute freeze on new commissions could leave newer communities unrepresented in public spaces. The solution is not to abandon care but to include lifetime costs in each proposal and reconsider works that no longer suit their location. Temporary exhibitions can add variety without creating permanent maintenance obligations. Public consultation should compare these options openly instead of treating a new monument as the only visible form of cultural support.', 'care for existing works deserves priority because it safeguards lasting public value, but responsible new commissions remain possible when their future costs and community purpose are clear.'],
  ['packaging-delivery', 'Charging for disposable takeaway containers', 'Environment and business', 'Restaurants should charge customers separately for disposable takeaway containers. To what extent do you agree or disagree?', 'A disposable container is often treated as free even though someone must pay for its production and disposal.', 'I agree with a separate, visible charge when safe reusable alternatives are genuinely available.', 'Including packaging in the price hides its cost and gives customers little reason to refuse it. A small separate charge makes the choice explicit and can encourage a regular customer to bring a suitable container. Restaurants may then find it worthwhile to offer a deposit system, in which clean containers are returned and used again rather than bought and discarded after one meal.', 'The scheme must account for hygiene and convenience. A traveller cannot always carry a box, and some foods need packaging that prevents leaks or contamination. Charges should therefore be transparent rather than punitive, with exemptions where reuse is unsafe. Restaurants also need practical cleaning procedures and accessible return points. Otherwise, customers merely pay more for the same waste while the promised alternative remains inconvenient.', 'a transparent container charge can reduce unnecessary waste, but it is justified by a workable reusable option rather than by adding another unavoidable fee to every meal.'],
];

const discussion: Plan[] = [
  ['homework-weekend', 'Weekends and school homework', 'Education', 'Some people think children should receive homework every weekend, while others believe weekends should be completely free of schoolwork. Discuss both views and give your opinion.', 'The weekend has competing roles as a time for recovery and an opportunity to consolidate learning.', 'I favour occasional, purposeful homework rather than either automatic weekly assignments or a complete prohibition.', 'Supporters of weekend homework point to the time needed to practise skills. A pupil who has just learned fractions may benefit from solving a few problems independently before the next lesson. Regular review can expose misunderstandings early, and a short task is easier to complete carefully when the child is not already tired from a school day.', 'Those opposing it value family relationships, play and physical activity. A child with several teachers may receive hours of separate assignments that collectively remove those opportunities. This objection is strongest against poorly coordinated work. Teachers could set a small project only when it serves a clear learning purpose, while agreeing a shared limit and protecting genuinely free weekends.', 'limited, coordinated tasks can support learning, but compulsory homework every weekend risks sacrificing development that takes place beyond the classroom.'],
  ['urban-trees-parking', 'Street trees or parking places', 'Cities and environment', 'Some people believe city streets should have more trees even if parking spaces are removed. Others think parking is more important. Discuss both views and give your opinion.', 'Street space is limited, and deciding how to use it affects both access and comfort.', 'I generally favour additional trees, with essential accessible parking retained close to important destinations.', 'Advocates of trees emphasise shade, drainage and a more pleasant walking environment. In a neighbourhood with long summer heatwaves, a mature canopy can make the journey to shops tolerable for older residents. Trees also absorb some rainfall where paved surfaces would otherwise send it directly into drains, so their benefits extend beyond appearance.', 'Parking supporters argue that shops and services must remain reachable for drivers, especially customers with disabilities or heavy purchases. Their concern should not be dismissed. However, preserving every ordinary parking bay may benefit a small number of stationary vehicles at the expense of many pedestrians. Designated accessible bays, loading spaces and nearby shared parking can meet genuine access needs while releasing other space.', 'street trees offer wider public benefits than unrestricted curbside parking, but a successful redesign must preserve access for people who cannot reasonably walk from a distant car park.'],
  ['exam-open-book', 'Open book examinations', 'Education and assessment', 'Some people prefer open book examinations, while others believe students should be tested without access to reference materials. Discuss both views and give your opinion.', 'The choice of examination format reflects what a course considers important to learn.', 'I prefer a mixture, with open book tasks for application and restricted tests for essential knowledge.', 'An open book examination can assess how students use information rather than how many facts they remember. A law student analysing an unfamiliar dispute still needs to choose the relevant rule and explain its significance, even with a statute available. Properly designed questions demand judgement, and access to references resembles the conditions of many professional decisions.', 'Closed book tests encourage students to internalise foundations that they may need quickly. A nurse cannot consult a long manual before recognising a dangerous symptom, for example. Yet testing obscure details can reward short term memorisation without lasting understanding. Courses should identify the knowledge genuinely needed from memory and use other assessments to examine research and complex reasoning.', 'neither format is universally superior: secure foundational knowledge and the intelligent use of references are different skills, and an assessment system should make room for both.'],
  ['hospital-visitors', 'Flexible hospital visiting hours', 'Health and family', 'Some people think hospital visiting hours should be flexible, while others prefer strict visiting schedules. Discuss both views and give your opinion.', 'Hospital visiting arrangements must balance emotional support against the demands of medical care.', 'I favour flexible access for close supporters within clear clinical and privacy boundaries.', 'Flexible visiting enables a relative working irregular hours to provide reassurance and help a patient communicate concerns. For someone with dementia, a familiar person can reduce confusion and assist staff in understanding usual behaviour. Rigid afternoon windows may exclude exactly the person best placed to help, particularly when travel to a specialist hospital is difficult.', 'Strict schedules make it easier to complete procedures, maintain quiet periods and protect other patients in shared rooms. These needs are legitimate, especially in intensive care. However, a fixed rule for every ward is unnecessarily blunt. Staff could agree individual arrangements, restrict the number of visitors and ask them to leave during treatment or when another patient needs privacy.', 'flexibility should be the default for supportive visits, with temporary restrictions based on actual clinical needs rather than an assumption that the same timetable suits every patient.'],
  ['tourism-entry-fee', 'Entrance charges at natural attractions', 'Tourism and environment', 'Some people think visitors should pay to enter popular natural attractions. Others believe access should always be free. Discuss both views and give your opinion.', 'Natural attractions need protection, but charging for access changes who can enjoy them.', 'I support modest charges at heavily used sites, coupled with affordable access for residents and low income visitors.', 'Supporters of fees argue that visitors cause costs through worn paths, litter and pressure on toilets or rescue services. A busy coastal reserve can use ticket income for boardwalks and wardens, reducing damage without relying entirely on taxpayers who may never visit. Booking and payment can also help managers keep numbers within the site’s capacity.', 'Opponents see nature as a common resource rather than a luxury experience. A high charge could exclude local families while allowing wealthy tourists unrestricted access. The answer is to separate necessary conservation funding from excessive commercial pricing. Free community days, concessions and transparent accounts would preserve a public right to experience nature while sharing the costs of protecting particularly vulnerable places.', 'carefully limited fees can fund conservation at crowded sites, but fair access and clear use of the revenue are essential to prevent public landscapes becoming exclusive products.'],
  ['work-four-day', 'A shorter working week', 'Employment', 'Some people support a four day working week, while others believe a five day week is necessary. Discuss both views and give your opinion.', 'A shorter working week promises more personal time but raises questions about service and productivity.', 'I support shorter hours where work can be redesigned effectively, rather than imposing an identical timetable on every occupation.', 'Supporters argue that fewer hours can reduce exhaustion and encourage more focused work. An office that removes repetitive meetings and unnecessary approvals may achieve the same output while allowing employees a regular day for care or rest. Better recovery can reduce absence and staff turnover, partly offsetting the apparent loss of working time.', 'Critics worry that factories, care homes and customer services cannot simply close one day without reducing output. They are right that physical coverage still needs staff. A compressed schedule of four very long days might even increase fatigue. Employers should test genuine reductions in hours with staggered teams where appropriate, measuring quality and workload rather than adopting a fashionable label.', 'a shorter week is worth testing, but its success depends on realistic staffing and process changes, not on expecting five days of demanding work to fit into four unchanged days.'],
  ['language-global-local', 'A global language and local languages', 'Language and culture', 'Some people think everyone should learn one common international language. Others believe protecting local languages is more important. Discuss both views and give your opinion.', 'International communication and local cultural expression serve different but equally meaningful purposes.', 'I favour learning a shared language alongside active support for local languages, rather than treating the goals as incompatible.', 'A common language reduces barriers in science, travel and international trade. A small business can contact overseas suppliers without needing a translator for every message, while researchers can compare work produced in different countries. Learning that language therefore offers practical opportunities, and denying access in the name of cultural protection could disadvantage the very communities being protected.', 'Supporters of local languages stress that vocabulary carries history, humour and knowledge not easily transferred elsewhere. If schools and public services use only a dominant language, children may stop speaking their family language even at home. Bilingual education, local publishing and accessible public information can keep the language useful. A common international language need not replace it as the medium of community life.', 'shared communication and linguistic diversity can reinforce each other when education adds a language instead of removing one, so policy should expand opportunity without erasing local expression.'],
  ['technology-elderly', 'Digital services and older citizens', 'Technology and society', 'Some people think older people should adapt to online public services. Others believe public services should retain face to face access. Discuss both views and give your opinion.', 'Moving a service online can simplify administration while making it harder for some people to obtain help.', 'I support digital training and convenient online options, but essential services must retain an accessible human route.', 'Those favouring adaptation point out that online forms can save a long journey and allow appointments to be arranged at any time. Many older adults use technology confidently and appreciate this independence. Training at libraries, simple interfaces and telephone guidance can help others gain useful skills, reducing the assumption that age automatically makes someone incapable of managing digital tasks.', 'Supporters of face to face access focus on people whose eyesight, memory, income or circumstances make online procedures difficult. A complex benefit application can require explanation that a web page cannot provide. Removing the human option before these needs are met would turn administrative efficiency into exclusion. Shared service counters and appointment based assistance can preserve help without duplicating every digital process.', 'people should be supported in using digital services, but access to essential rights must not depend on owning a device or completing a form without meaningful assistance.'],
  ['school-uniform-choice', 'Individual choice in school clothing', 'Education and identity', 'Some people favour strict school uniforms, while others think pupils should choose their own clothes. Discuss both views and give your opinion.', 'School clothing rules influence belonging, personal expression and the daily cost of attendance.', 'I favour a flexible, inexpensive dress code over either highly prescriptive uniforms or completely unrestricted clothing.', 'Uniform supporters believe shared clothing reduces visible competition over brands and makes pupils easier to identify on trips. It can also simplify a family’s morning routine. These benefits are most credible when clothing is affordable and widely available; requiring a special blazer from one supplier can create the very economic division the uniform is meant to reduce.', 'Those supporting choice argue that pupils should practise making personal decisions and that comfort affects participation. A rigid design may be unsuitable for different bodies, climates or religious needs. A common set of practical rules on safety and respectful coverage can address genuine concerns while allowing colour and style choices. Teachers would then spend less time enforcing minor differences with no educational importance.', 'a modest dress code can preserve practical benefits and limit status competition while allowing enough choice to respect pupils’ comfort, identity and family budgets.'],
  ['zoos-conservation', 'The role of modern zoos', 'Environment and animal welfare', 'Some people believe zoos play an important role in conservation. Others think keeping wild animals in zoos is unacceptable. Discuss both views and give your opinion.', 'Modern zoos claim a conservation purpose, but captivity still raises serious welfare questions.', 'I support only institutions that can demonstrate conservation value and meet species specific welfare needs.', 'Supporters point to breeding programmes and veterinary research that can help endangered populations. A species whose habitat has been severely damaged may need a protected breeding group before reintroduction becomes possible. Public education can also build support for habitat protection, especially when visitors see how behaviour and ecosystems are connected rather than simply watching animals perform.', 'Opponents argue that some animals cannot exercise natural behaviours in confined settings. A wide ranging predator may remain physically healthy while suffering from a lack of space and choice. This concern should set limits on what a zoo keeps, not be answered by a general conservation slogan. Independent welfare inspections and evidence of genuine conservation work are more convincing than visitor numbers or attractive enclosures.', 'zoos are defensible only under demanding conservation and welfare standards, and animals whose needs cannot be met should not be kept merely because they attract an audience.'],
  ['city-growth-outward', 'Building up or building out', 'Housing and cities', 'Some people prefer taller apartment buildings in existing cities, while others favour new housing on surrounding land. Discuss both views and give your opinion.', 'Growing cities must choose how to provide homes without making daily life more difficult.', 'I favour well planned denser housing near services, with limited outward growth where infrastructure can genuinely support it.', 'Building within the existing city can use established transport, schools and utilities while protecting farmland. Residents near shops and stations may not need a car for every task, so density can reduce traffic per household. However, taller housing must include daylight, shared space and family sized homes rather than treating the maximum number of units as the only measure of success.', 'Outward expansion offers room for gardens and lower buildings, which some households prefer. It can also relieve pressure where inner city sites are scarce. Yet cheap land becomes less affordable once roads, drainage and long commutes are counted. New districts should be planned around public transport and essential services from the start, otherwise the city inherits decades of car dependence and infrastructure costs.', 'density near existing services should normally take priority, but thoughtful design matters more than height alone and some outward growth is acceptable when its full costs are acknowledged.'],
  ['news-local-global', 'Local news and international news', 'Media and citizenship', 'Some people think news organisations should focus on local events, while others prefer more coverage of international affairs. Discuss both views and give your opinion.', 'News connects readers to decisions made both near their homes and far beyond national borders.', 'I believe a balanced service needs strong local reporting as well as clear explanations of major international events.', 'Local journalism can examine issues that large national outlets overlook, such as a hospital closure or a council contract. Residents can act on this information through meetings, complaints or votes. Without reporters attending local proceedings, decisions may receive little scrutiny, so attention to everyday institutions is a democratic function rather than merely a preference for familiar stories.', 'International reporting explains forces that local experience alone cannot reveal. A change in overseas energy supply may affect household bills, while conflict can reshape migration and trade. Readers need these connections to interpret events accurately. However, copying dramatic foreign headlines without explaining their relevance is less useful than investing in analysis. Cooperation between newsrooms can provide global context without eliminating local expertise.', 'local accountability and international understanding are complementary goals, and newsrooms should protect original local reporting while explaining how wider events influence the communities they serve.'],
  ['university-industry', 'Industry partnerships at universities', 'Education and research', 'Some people think universities should work closely with businesses. Others believe universities should remain independent of commercial interests. Discuss both views and give your opinion.', 'Business partnerships can bring resources to universities while also influencing what researchers investigate.', 'I support cooperation under transparent rules that protect academic freedom and publication of results.', 'Businesses can offer equipment, practical problems and placements that a university could not fund alone. An engineering team working with a water company might test a new filter under realistic conditions rather than only in a laboratory. Students gain experience, and useful discoveries can reach the public sooner when an organisation has the capacity to manufacture or operate them.', 'Those defending independence worry that sponsors may suppress unwelcome findings or direct attention only towards profitable topics. A public health study loses value if the funding company can veto its results. Universities therefore need published agreements, conflict disclosures and control over academic conclusions. Basic research with uncertain commercial returns also requires protected funding so that partnership does not define the entire institution’s purpose.', 'industry cooperation can be valuable, but the university must retain authority over its findings and a research agenda wider than the immediate interests of its commercial partners.'],
  ['water-pricing', 'Charging for household water', 'Environment and public services', 'Some people think water should be free to every household, while others believe charging for it is necessary. Discuss both views and give your opinion.', 'Water is essential to life, yet supplying clean water and treating wastewater require substantial resources.', 'I favour an affordable basic allowance with charges for higher use rather than unlimited free supply.', 'Supporters of free water emphasise health and dignity. A low income family should not reduce washing or drinking because it cannot pay a bill, and the consequences of poor hygiene affect the whole community. A guaranteed basic supply recognises this public interest and prevents an essential service from being treated as an ordinary optional purchase.', 'Those supporting charges argue that pumps, treatment plants and repairs cannot operate without funding. Unlimited free use also gives little incentive to fix a leaking tap or avoid unnecessary garden watering. A graduated tariff can cover costs while protecting basic needs. Assistance should reflect household size and medical requirements, since identical allowances may be unfair to larger families or people with special health needs.', 'basic access should be protected, while proportionate charges above that level can support reliable infrastructure and discourage waste without denying households the water required for a healthy life.'],
  ['science-space-ocean', 'Researching space or the oceans', 'Science and public spending', 'Some people think research funding should prioritise space exploration, while others favour studying the oceans. Discuss both views and give your opinion.', 'Scientific budgets cannot investigate every unknown equally, so priorities need a clear public justification.', 'Both fields deserve support, but I would give greater additional funding to ocean research addressing immediate environmental risks.', 'Space research improves observation of weather and land use and can generate new engineering methods. Satellites also provide data that helps manage disasters, so the field is not limited to distant exploration with no practical return. Long term missions can advance fundamental knowledge and inspire students to study science, benefits that are difficult to measure in a single annual budget.', 'Ocean research offers direct insight into fisheries, carbon storage and coastal hazards that affect millions of people. A better understanding of marine heatwaves could help fishing communities adapt before livelihoods collapse. Much of the deep sea remains poorly understood despite its importance to Earth’s systems. Prioritising these questions does not require abandoning satellites; the two fields can share information and equipment.', 'space science should continue, but pressing marine uncertainties justify a larger marginal investment in ocean research, particularly where the findings can protect ecosystems and coastal communities.'],
  ['sports-specialise', 'Early specialisation in children’s sport', 'Sport and childhood', 'Some people think children with sporting talent should specialise early. Others believe they should try several sports. Discuss both views and give your opinion.', 'A talented child’s training can build skill, but it can also narrow opportunities for healthy development.', 'I favour varied participation during childhood, followed by informed specialisation when the young athlete is ready.', 'Supporters of early specialisation note that complex techniques take years to develop. In a sport such as gymnastics, delaying structured practice may make elite competition harder to reach. A child who enjoys a particular activity can benefit from skilled coaching and a stable team, so a general rule against focused training would disregard both talent and personal enthusiasm.', 'Supporters of variety point to broader movement skills, friendships and lower pressure. Constant repetition can also increase overuse injuries, especially while children are growing. Trying swimming, cycling and team games may reveal strengths that an early decision would conceal. Coaches can retain technical sessions in a preferred sport while protecting rest, other activities and the freedom to change direction.', 'focused coaching can support talent, but childhood variety and autonomy should not be sacrificed to an adult prediction of future success in a single sport.'],
  ['family-meals', 'Shared meals and modern schedules', 'Family and society', 'Some people believe families should eat together every day. Others think this expectation is unrealistic in modern life. Discuss both views and give your opinion.', 'Eating together can strengthen relationships, but family members do not always share the same timetable.', 'I value regular shared meals without treating daily attendance as an inflexible test of a healthy family.', 'Supporters of daily meals see a dependable opportunity to talk without arranging a separate event. Parents may notice a child’s concerns while preparing food, and children can learn practical habits through shared cooking. A predictable meal can also provide emotional stability during a stressful period, making the routine valuable even when the food itself is simple.', 'Others point out that shift work, study and long travel times can make one daily gathering impossible. Insisting on it may create guilt or require an exhausted worker to eat at an unsuitable hour. Families can preserve the purpose through breakfast on some days, a weekly cooking session or another dependable conversation. The quality of attention matters more than whether everybody sits down at dinner every evening.', 'shared meals are a useful means of maintaining contact, but flexible routines that fit real working lives are preferable to an ideal that families can meet only at an unreasonable cost.'],
  ['heritage-modern-use', 'Reusing historic buildings', 'Culture and cities', 'Some people think historic buildings should be kept exactly as they are. Others believe they should be adapted for modern uses. Discuss both views and give your opinion.', 'A historic building can preserve evidence of the past while still needing a practical future.', 'I favour sensitive adaptation when it protects significant features and keeps the building accessible to the community.', 'Those opposing alteration fear that each small change can weaken historical authenticity. Replacing original windows or removing an old workshop interior may erase evidence that cannot be recreated later. For a building with rare construction techniques or important cultural meaning, careful preservation can provide educational value that a more commercially convenient interior would lose.', 'Supporters of adaptation argue that an unused building is likely to deteriorate. Converting a former warehouse into affordable studios can fund repairs and bring activity to an area, provided that distinctive structures remain visible. Conservation specialists should identify what must be protected and which later additions can change. A useful building with documented, reversible alterations may survive more successfully than an empty monument.', 'adaptation and preservation need not conflict when the important evidence is identified first, and a viable use can protect a historic building better than insisting that nothing ever changes.'],
  ['health-prevention-treatment', 'Preventing illness or treating it', 'Health and public spending', 'Some people think governments should spend more on preventing illness, while others favour improving treatment services. Discuss both views and give your opinion.', 'Health budgets face both the needs of people already ill and the possibility of preventing future harm.', 'I support stronger prevention funding without reducing essential treatment for current patients.', 'Prevention can reach people before a condition becomes painful and expensive. Safe walking routes, vaccination and help to stop smoking may reduce several future illnesses rather than address one patient at a time. Benefits can extend to households through fewer missed working days, so prevention should not be dismissed simply because the avoided cases are less visible than hospital queues.', 'Treatment advocates rightly stress that people with urgent needs cannot wait for population health to improve. A screening programme also achieves little if a detected condition cannot be treated promptly. Hospitals need skilled staff and reliable equipment now. Budget decisions should therefore examine which preventive measures have strong evidence while protecting necessary clinical capacity, rather than treating all prevention as automatically cheaper or more effective.', 'prevention deserves a greater role because avoidable illness imposes lasting costs, but a credible health system must also provide timely treatment and connect early detection to actual care.'],
  ['citizen-juries', 'Experts and citizens in public decisions', 'Society and government', 'Some people believe important public decisions should be made by experts. Others think ordinary citizens should have a greater role. Discuss both views and give your opinion.', 'Public decisions require technical knowledge as well as an understanding of how policies affect everyday life.', 'I favour informed citizen participation supported by experts, with elected institutions remaining accountable for the final decision.', 'Experts can assess risks that are not obvious from personal experience. An engineer understands the safety limits of a bridge, and an epidemiologist can explain why an outbreak may spread. Ignoring such knowledge can produce costly mistakes. Technical evidence should therefore set out what is feasible and what uncertainty remains before public preferences are turned into a detailed plan.', 'Citizens contribute knowledge about daily burdens and acceptable trade offs. A technically efficient transport scheme may fail people who care for relatives or work unusual hours. A representative citizens’ panel, given time to question specialists, can expose these effects and suggest alternatives. Participation should be designed to include less confident voices rather than rely only on whoever attends an open meeting.', 'expert advice and citizen judgement perform different functions, and combining them transparently can produce more legitimate decisions than granting unquestioned authority to either group alone.'],
];

const advantages: Plan[] = [
  ['shared-laundry', 'Shared laundry facilities in apartment buildings', 'Housing and consumption', 'More apartment buildings now provide shared laundry rooms instead of space for a washing machine in every flat. Do the advantages outweigh the disadvantages?', 'Shared household equipment can save space, although residents lose some control over daily routines.', 'I believe shared laundries have greater advantages in small apartment buildings if access and maintenance are reliable.', 'One properly maintained room can serve many households without each buying a large appliance. Residents gain storage or living space, and efficient machines can use less water per load. A tenant who moves frequently also avoids transporting a heavy washer, while the building can arrange repairs centrally instead of leaving an individual household without functioning equipment.', 'The disadvantage is competition for machines at convenient times, particularly for parents dealing with urgent washing. A poorly managed room may also become unhygienic. Booking slots, a few machines available without reservations and prompt fault reporting can reduce these problems. The model is much less attractive where the room is difficult to reach or management does not maintain it.', 'space and resource savings outweigh the inconvenience when sufficient machines and dependable management are provided, but a shared room should not be used merely to remove facilities from flats.'],
  ['self-service-checkout', 'Self service shopping checkouts', 'Technology and employment', 'Self service checkouts are becoming common in supermarkets. Do their advantages outweigh their disadvantages?', 'Automation changes a supermarket visit for customers and alters the work required from staff.', 'For many stores, the benefits do not outweigh the disadvantages unless customers retain a well staffed conventional option.', 'Self service can speed up a small purchase when a customer is familiar with the system. Staff can then assist with stock, deliveries or problems rather than scan every item. It also permits several tills to operate in a limited area, which can be helpful at busy times when queues would otherwise block aisles.', 'However, errors with weighed items, payment or age checks can make the apparent convenience disappear. Shoppers with limited vision or dexterity may find the process especially difficult. If automation is accompanied by excessive staff reductions, one assistant must manage many interrupted machines. Retaining human checkouts and adequately supporting the new stations is therefore part of the real cost, not an optional addition.', 'self service is useful as a choice, but replacing most staffed tills can shift work and frustration onto customers, making the overall benefit far less certain than a simple labour saving suggests.'],
  ['subscription-books', 'Digital book subscriptions', 'Reading and technology', 'Many readers now pay a monthly subscription for access to digital books rather than buying individual books. Discuss the advantages and disadvantages.', 'A book subscription replaces ownership of particular titles with temporary access to a changing catalogue.', 'The arrangement suits frequent exploratory readers, but it is less satisfactory for people building a lasting personal library.', 'A subscription lowers the risk of trying an unfamiliar author. Someone can sample a history book, decide it is unsuitable and move to a novel without paying separately for both. Immediate access is also valuable where physical bookshops are distant, and adjustable text can help readers who struggle with small print. The benefit depends on a catalogue containing books they actually want.', 'The disadvantage is that access ends when payments stop, and a publisher may remove a favourite title without the reader’s agreement. A light reader can also spend more over a year than the cost of buying a few books. Tracking reading habits raises privacy concerns, so subscribers should understand data policies and avoid assuming that a downloaded book has become their permanent property.', 'subscriptions offer variety and convenience, while individual purchases offer lasting access and predictability; the better choice depends on reading frequency, desired titles and the value placed on ownership.'],
  ['city-congestion-charge', 'Charging cars to enter city centres', 'Transport and environment', 'Some cities charge private cars to enter busy central areas. Do the advantages outweigh the disadvantages?', 'A congestion charge aims to make limited road space work better, but it also changes the cost of access.', 'Its advantages outweigh its disadvantages when public transport and targeted exemptions make the policy fair.', 'Fewer cars can improve bus reliability, reduce street noise and allow delivery vehicles to complete trips more predictably. A charge also makes drivers consider whether a journey really requires a car. If revenue funds frequent buses and safer walking routes, people who switch modes gain practical benefits instead of simply paying a penalty for entering the city.', 'The immediate burden can fall on workers who travel at hours when buses are infrequent. Small firms may also face costs transporting tools that cannot be carried on public transport. Exemptions should therefore address documented needs, rather than favouring every wealthy driver who can afford a different vehicle. The boundary must be monitored to prevent traffic and parking problems being displaced into neighbouring districts.', 'a well designed charge can improve access overall, but transport alternatives and carefully justified exemptions are essential to ensure that reduced traffic is not achieved through unfair exclusion.'],
  ['apprenticeship-salary', 'Paid apprenticeships after school', 'Education and work', 'More school leavers choose paid apprenticeships instead of going straight to university. What are the advantages and disadvantages of this development?', 'An apprenticeship lets a young person earn while learning, but it ties early education to a particular workplace.', 'This development is welcome when programmes provide recognised qualifications and broad skills rather than cheap labour.', 'Paid training opens a route for students who cannot afford several years without an income. Working alongside experienced staff can also make abstract ideas concrete; an apprentice electrician learns why a safety procedure matters while applying it under supervision. Employers benefit from developing skills they actually need, and learners can test whether the occupation suits them before making a larger commitment.', 'The risk is excessive dependence on one company or narrow task. An apprentice trained only to operate a particular machine may struggle if the factory closes. Quality assurance should require off the job learning, qualified supervision and transferable certification. Young people should also receive impartial advice, because an immediate wage can obscure differences in future progression between a sound training programme and routine low paid work.', 'apprenticeships can widen opportunity and connect learning to practice, but their long term value depends on portable qualifications, genuine teaching and an informed choice rather than the attraction of wages alone.'],
  ['home-medical-monitoring', 'Health monitoring at home', 'Health and technology', 'Patients increasingly use devices at home to send health measurements to doctors. Do the advantages outweigh the disadvantages?', 'Remote monitoring brings some medical information into everyday life without repeated clinic visits.', 'For suitable conditions, its benefits outweigh the risks if clinicians explain the limits and protect patient data.', 'Regular measurements can reveal a pattern that a brief appointment misses. A person managing blood pressure might send readings taken under normal conditions, allowing a clinician to review treatment more intelligently. It can also reduce travel for patients who live far from a clinic, reserving face to face appointments for situations that require examination or detailed discussion.', 'Devices can produce inaccurate readings, and constant monitoring may increase anxiety rather than improve care. A patient may also assume that every uploaded result is checked immediately when the system is not an emergency service. Clear instructions, validated equipment and a defined response process are therefore necessary. Patients unable to use digital tools must retain ordinary care rather than be disadvantaged by the new arrangement.', 'home monitoring is a useful extension of clinical care, not a replacement for medical judgement, and its advantages depend on accurate tools, realistic expectations and an accessible alternative.'],
  ['community-fridge', 'Community food sharing', 'Food and society', 'Community fridges allow people to leave unwanted food for others to take. Discuss the advantages and disadvantages of this practice.', 'Sharing surplus food can reduce waste while making a small practical contribution to local needs.', 'Community fridges are worthwhile when clear food safety procedures and respectful access are in place.', 'A household leaving for a holiday can share unopened food rather than throw it away, and a bakery can contribute bread still suitable to eat. These small transfers save resources already used in production. An open fridge can also avoid the formal eligibility checks associated with some assistance schemes, allowing a neighbour facing a temporary shortage to receive help discreetly.', 'The disadvantage is uncertainty about storage, expiry dates and responsibility when food is unsafe. Irregular donations also make the fridge unsuitable as a guaranteed source of nutrition. Volunteers should accept clearly labelled items, maintain temperatures and remove unsuitable food promptly. Local authorities can provide basic guidance without turning a small sharing project into an administrative burden that volunteers cannot manage.', 'food sharing offers environmental and social benefits, but it needs consistent safety management and should supplement reliable food assistance rather than be mistaken for a complete solution to hunger.'],
  ['tourism-home-rent', 'Renting spare rooms to visitors', 'Tourism and housing', 'Many residents rent spare rooms in their homes to tourists for short periods. What are the advantages and disadvantages?', 'Short stays can bring visitors into ordinary neighbourhoods and provide income to households.', 'Renting a genuine spare room can be beneficial, although it needs boundaries that protect neighbours and housing supply.', 'Hosts can earn money from space that would otherwise remain unused, helping pay maintenance or household bills. Visitors may learn more about everyday life than they would in an isolated resort, and spending can reach neighbourhood cafés. This arrangement is particularly useful during an occasional festival, when existing hotels cannot accommodate everybody without building permanent capacity for a brief peak.', 'Privacy, noise and safety are concerns for both hosts and neighbours. The effects become more serious when investors remove entire homes from the long term rental market, which is different from sharing a spare room. Registration, occupancy limits and clear complaint procedures can distinguish the two activities. Hosts also need realistic information about insurance and tax instead of assuming that an online booking guarantees protection.', 'limited home sharing can distribute tourism income and use existing space efficiently, but regulation must separate it from commercial conversion of housing and address the everyday interests of neighbouring residents.'],
  ['school-digital-textbook', 'Replacing school textbooks with tablets', 'Education and technology', 'Some schools replace printed textbooks with tablets containing digital materials. Do the advantages outweigh the disadvantages?', 'Digital textbooks offer convenience, yet the device used to read them introduces additional demands.', 'The advantages are strongest in a mixed system; complete replacement can create disadvantages that outweigh the savings.', 'A tablet can carry several subjects without a heavy bag and can update an outdated diagram quickly. Search, audio and enlarged text also help some learners access material more independently. Interactive demonstrations may clarify a process that a static page cannot show, provided that the activities support the lesson rather than merely entertain pupils with animations.', 'However, charging, repairs and distraction can interrupt learning, while a broken or forgotten device may remove access to every subject at once. Long reading tasks are also uncomfortable for some pupils on a screen. Schools should calculate replacement and support costs, keep printed alternatives and restrict unrelated apps during lessons. Digital access is valuable, but it does not establish that paper has become educationally useless.', 'tablets can improve accessibility and selected learning activities, while retaining printed resources makes the system more resilient and avoids forcing every pupil and every task into the same format.'],
  ['workplace-open-office', 'Open plan offices', 'Employment and design', 'Many employers use open plan offices instead of separate rooms. What are the advantages and disadvantages of this arrangement?', 'An open office places colleagues close together, but proximity does not automatically produce effective cooperation.', 'The arrangement is useful for some collaborative tasks, provided that quiet work and private conversations have adequate space.', 'Shared seating can make quick questions easier and allow a new employee to hear how experienced colleagues solve everyday problems. It may also use floor space flexibly as teams change. In a project requiring rapid coordination, seeing that a colleague is available can be more efficient than scheduling a formal meeting for every minor decision.', 'The same environment can make concentration difficult. Phone calls and passing conversations interrupt complex writing, and sensitive discussions cannot be held comfortably beside unrelated colleagues. Employers should provide quiet rooms and agree interruption rules rather than assume staff will simply adapt. Measuring completed work and employee wellbeing is more informative than praising an attractive room or the number of desks it accommodates.', 'open offices can support informal communication, but without quiet and private alternatives they may reduce the focused work on which the organisation depends.'],
  ['cashless-market', 'Cashless street markets', 'Money and society', 'Some street markets now accept only digital payments. Do the advantages outweigh the disadvantages?', 'Digital payments can simplify a market transaction, but making them compulsory changes who can participate.', 'The benefits do not outweigh the disadvantages of excluding cash entirely in an ordinary community market.', 'Traders avoid holding large amounts of cash and can keep clearer records of sales. A customer may also complete a purchase without searching for exact change, while electronic receipts help resolve disputes. These benefits make a digital option valuable, particularly for vendors who previously lost time visiting a bank or dealing with counterfeit notes.', 'An exclusive system excludes people without suitable accounts, charged phones or reliable connectivity. A temporary network failure can stop trade for every stall at once. Small vendors may also pay transaction fees that consume a meaningful share of a low value sale. Retaining cash alongside digital methods provides resilience and choice without requiring traders to abandon the convenience of electronic payments.', 'digital payment options improve convenience, but a cashless requirement imposes avoidable barriers and dependence on technology, making a mixed payment system preferable for inclusive local markets.'],
  ['online-skill-certificates', 'Short online qualifications', 'Education and employment', 'Workers increasingly take short online courses that offer certificates. What are the advantages and disadvantages of this trend?', 'Short online courses make additional learning possible without a lengthy break from employment.', 'They are a useful supplement to experience and substantial qualifications, but their value varies considerably.', 'A worker can address an immediate gap, such as spreadsheet analysis or a new safety standard, while studying around a job. Short courses also allow someone to test an interest before committing to a costly programme. When assessments require genuine application, the certificate can provide evidence of a specific skill and help a manager identify employees ready for different responsibilities.', 'The disadvantage is uncertainty about quality. A certificate awarded after watching videos may say little about competence, and employers may struggle to distinguish it from rigorous training. Learners can also collect badges without connecting the topics into deeper understanding. Independent standards, clear assessment descriptions and opportunities to practise at work are needed so that convenience does not become a substitute for meaningful learning.', 'short online courses expand access to targeted study, but learners and employers should judge the assessment and practical relevance rather than assume that every digital certificate represents equivalent achievement.'],
  ['vertical-farming', 'Growing vegetables inside urban buildings', 'Agriculture and technology', 'More businesses grow vegetables in indoor urban farms. Do the advantages outweigh the disadvantages?', 'Indoor urban farming promises nearby produce while replacing some natural growing conditions with technology.', 'It has advantages for selected crops, but it cannot be assumed to outperform ordinary farming in every setting.', 'Controlled conditions can protect leafy vegetables from drought and pests, allowing predictable supply close to customers. Recirculated water may also reduce consumption, and unused buildings can serve a productive purpose. Short delivery routes are helpful for delicate leaves that lose quality quickly, making an indoor farm particularly attractive where suitable agricultural land is distant or scarce.', 'The disadvantage is electricity used for lighting, ventilation and temperature control. An apparently local vegetable may carry a large environmental cost if the energy source is highly polluting. Equipment and skilled maintenance also raise prices. Farms should compare total resource use with seasonal outdoor alternatives and select crops suited to the system, rather than presenting indoor production as a realistic replacement for all agriculture.', 'urban indoor farms can provide reliable specialist produce, but their overall advantage depends on energy, climate and crop choice, so careful comparison is preferable to either enthusiasm or rejection based on novelty.'],
  ['language-auto-translation', 'Using automatic translation when travelling', 'Language and tourism', 'Travellers increasingly use automatic translation apps instead of learning the local language. Discuss the advantages and disadvantages.', 'Translation apps reduce practical language barriers, although they do not reproduce every aspect of communication.', 'They are valuable tools for access and safety, but they work best alongside a willingness to learn basic local expressions.', 'An app can help a visitor read an allergy warning or explain a transport problem in a language they have never studied. This widens access to travel and can reduce stress in unfamiliar situations. It is particularly useful for short visits, when learning enough vocabulary for a detailed medical or administrative conversation would not be realistic beforehand.', 'Automatic output can misinterpret humour, politeness or an ambiguous instruction. Depending entirely on a phone may also make a conversation slower and less personal, especially where connectivity is unreliable. Travellers should learn greetings and important emergency phrases, check critical information with a human when possible, and use downloaded language packs. The tool assists understanding, but it should not create false confidence that every message is accurate.', 'translation technology makes travel more accessible, while basic language learning and caution about sensitive messages preserve the human connection and reliability that an app cannot guarantee.'],
  ['deposit-cups', 'Returnable cups for takeaway drinks', 'Consumption and environment', 'Some cafés use returnable cups with a deposit instead of disposable cups. Do the advantages outweigh the disadvantages?', 'A returnable cup changes packaging from a single purchase into a small shared system.', 'Its benefits outweigh the inconvenience where customers can return cups easily and cleaning is efficient.', 'Repeated use spreads the resources required to make a cup across many drinks, reducing the stream of disposable packaging. A commuter can return yesterday’s cup at another participating café rather than carry a personal mug all day. Shared return points make reuse possible for people who do not plan every purchase, expanding it beyond especially committed environmental consumers.', 'However, cups that are lost or rarely returned provide little benefit, and washing requires water and energy. Deposits may also deter someone with very little money. The scheme should use durable designs, convenient collection and published evidence of return rates. Staff need a safe cleaning process, while cash refunds or simple returns prevent technology from becoming another barrier to participating.', 'a well organised deposit network can reduce packaging waste, but high return rates and accessible refunds determine its success more than the mere presence of a reusable cup.'],
  ['shared-workspaces', 'Working in a shared office', 'Employment and community', 'Freelancers increasingly rent desks in shared workspaces rather than working at home. What are the advantages and disadvantages?', 'A shared workspace offers professional facilities without the commitment of a private office.', 'It can be useful for people who need separation and contact, although the cost and atmosphere do not suit everyone.', 'Working outside the home creates a boundary that can protect both concentration and personal life. A freelancer in a noisy household may gain dependable internet, a meeting room and an appropriate place to speak with clients. Contact with other workers can also reduce isolation and lead to useful exchanges, even when they do not belong to the same organisation.', 'Rent is a disadvantage for someone with irregular income, and an open workspace may reproduce the distractions they hoped to escape. Informal networking can become another demand on attention rather than a benefit. Flexible day passes, quiet areas and clear rules on calls would make the arrangement more useful. The decision should follow the person’s actual working pattern, not the belief that a fashionable shared office guarantees productivity.', 'shared workspaces offer facilities and social contact, but they are worthwhile only when these benefits exceed the cost and the environment supports the particular tasks a freelancer needs to complete.'],
  ['school-community-garden', 'School gardens shared with neighbours', 'Education and community', 'Some schools open their gardens to local residents outside school hours. Discuss the advantages and disadvantages.', 'A school garden can serve education during the day and become a community resource afterward.', 'Shared use is worthwhile when supervision, access and responsibilities are clearly agreed.', 'Residents may contribute gardening knowledge, tools and time that improve the space for pupils. Families without private gardens also gain somewhere to grow food and meet neighbours. A joint planting project can connect classroom lessons to real seasonal change, while older residents have an opportunity to pass on practical skills instead of the school relying entirely on paid external workshops.', 'The arrangement creates responsibilities for safeguarding, maintenance and security. A damaged greenhouse can affect lessons, and open access cannot overlap carelessly with activities involving children. Defined hours, separate entrance routes and named coordinators can manage these concerns. Participants should agree how produce and tasks are shared, because an informal expectation that a few volunteers will do all the work may eventually cause resentment.', 'shared gardens can create educational and community value from existing land, provided that clear arrangements protect pupils, distribute work fairly and make access more reliable than an occasional invitation.'],
  ['digital-concerts', 'Watching live performances online', 'Culture and technology', 'Musicians increasingly stream live concerts online as well as performing for an audience in person. Do the advantages outweigh the disadvantages?', 'A streamed concert reaches beyond the room, although it offers a different experience from attending.', 'The advantages outweigh the drawbacks when streaming complements live performance and artists are fairly paid.', 'Online access allows a listener with limited mobility or a distant home to enjoy a performance otherwise unavailable. A small group can also build an audience beyond its local venue without funding an international tour. Affordable digital tickets may introduce unfamiliar music to new listeners, who later support recordings or attend a nearby performance when the opportunity arises.', 'The disadvantages include weaker sound quality, screen distractions and the loss of shared atmosphere. Musicians may also face pressure to offer streams cheaply while production costs remain substantial. Clear licensing and payment arrangements are essential, and viewers should understand the limits of the format. Streaming is less beneficial if a platform gains most of the income while encouraging audiences to regard performances as free background content.', 'streaming broadens cultural access and can support musicians, but it should be a properly funded additional format rather than a supposedly equivalent replacement for the collective experience of a live venue.'],
  ['flexible-school-start', 'Different starting times for schools', 'Education and transport', 'Some cities stagger the starting times of schools instead of having all schools open together. What are the advantages and disadvantages?', 'Coordinating school schedules can affect transport demand as well as household routines.', 'Staggered starts can improve travel, but the timetable must account for siblings and working parents.', 'Spreading arrivals reduces the sudden concentration of buses and cars around a single morning peak. A transport operator may use the same bus for two schools rather than purchase extra vehicles needed for only a brief period. Less crowded journeys can also improve safety and make arrival more predictable, helping lessons begin without repeated disruption from traffic delays.', 'However, a parent with children at different schools may face a prolonged sequence of journeys. A later start can also conflict with work unless supervised early arrival is available. Authorities should coordinate neighbouring schools and consult families before choosing times. The savings in transport should partly support breakfast clubs or childcare, so that a more efficient public timetable does not simply transfer hidden costs to households.', 'staggering can make school transport safer and more efficient, but its advantages depend on coordination and support for families whose daily commitments would otherwise become harder to manage.'],
  ['slow-tourism', 'Staying longer in one destination', 'Tourism and environment', 'More tourists choose to stay longer in one destination rather than visit several places on a single trip. Discuss the advantages and disadvantages.', 'A slower holiday changes both the visitor’s experience and the way tourism income is distributed.', 'Longer stays usually offer a richer experience, although they reduce variety and may concentrate pressure in popular places.', 'Remaining in one area allows time to understand ordinary routines instead of rushing between landmarks. A visitor may use local shops, take a language lesson and travel by public transport, spreading spending beyond a single tour company. Fewer transfers can also reduce the fuel and stress associated with repeatedly packing, travelling and checking into new accommodation.', 'The disadvantage is missing the variety a traveller hoped to experience, especially when international travel is rare. A long stay in a heavily visited neighbourhood can also add pressure to housing and services rather than solve tourism problems. Choosing suitable accommodation, visiting less crowded areas and respecting local routines matter more than duration alone. Slow travel is a useful option, not proof that every extended visit is sustainable.', 'a longer stay can deepen understanding and reduce repeated travel, but the best choice depends on the destination’s capacity and the visitor’s aims rather than the number of nights alone.'],
];

const problems: Plan[] = [
  ['flood-basement-homes', 'Basement homes and heavy rain', 'Housing and environment', 'More people in crowded cities live in basement apartments that are vulnerable to flooding. What problems does this create, and what solutions can you suggest?', 'Low cost basement housing can place residents directly in the path of floodwater.', 'The main problems are danger to life and repeated displacement, so housing standards and safer alternatives are needed together.', 'Water can rise quickly below street level, blocking a door before a sleeping tenant notices. Even a smaller flood can destroy belongings and leave damp conditions that damage health. Residents with little money may then return to the same unsafe home because they cannot afford another deposit, turning a single storm into continuing housing insecurity.', 'Authorities should identify high risk buildings, require alarms and accessible escape routes, and prohibit occupation where safety cannot be achieved. These rules must accompany relocation support or tenants will move into equally hidden accommodation. Affordable homes on safer sites, assistance with deposits and improved neighbourhood drainage address the danger without making the poorest residents bear the entire cost.', 'physical safeguards reduce immediate risk, while affordable relocation prevents enforcement from replacing a flooding problem with homelessness; neither approach is adequate on its own.'],
  ['tourist-path-erosion', 'Damage to popular walking trails', 'Tourism and environment', 'Popular walking trails are being damaged by increasing visitor numbers. What problems does this cause, and how can they be addressed?', 'A natural trail can deteriorate faster than vegetation and maintenance teams can repair it.', 'Erosion and wildlife disturbance require better route management rather than unrestricted access or permanent closure.', 'Repeated walking compacts soil and widens a path as visitors step around muddy sections. Rain then carries exposed soil downhill, damaging nearby streams and making the route unsafe. Noise and dogs can also disturb nesting wildlife, while an unattractive, degraded trail weakens the experience that originally attracted visitors and may affect local tourism income.', 'Raised walkways in vulnerable sections and seasonal closures can protect soil while keeping most of the route accessible. Clear directions should explain why leaving the marked path causes harm. At particularly sensitive sites, timed reservations can spread demand. Visitor income should support maintenance, and alternative trails need promotion so that restrictions do not merely concentrate the same crowd elsewhere.', 'trail protection should combine durable design, ecological timing and demand management, preserving meaningful access without allowing the landscape to be worn away by its own popularity.'],
  ['delivery-rider-safety', 'Safety pressures on delivery riders', 'Employment and transport', 'Delivery riders in many cities face pressure to complete orders very quickly. What problems does this create, and what solutions are possible?', 'Rapid delivery promises can create risks that are carried mainly by the person making the journey.', 'Unsafe riding and insecure earnings need changes to platform incentives as well as safer streets.', 'A rider paid per order may feel compelled to cross junctions hurriedly or check directions while moving. Bad weather makes the conflict worse because delays increase while safe riding becomes more difficult. Injuries harm riders and other road users, and someone classified as self employed may lose income immediately while recovering, encouraging further risk taking to cover basic costs.', 'Platforms should allow realistic travel times and avoid penalising workers for documented traffic or safety delays. Guaranteed minimum earnings and insurance would reduce the pressure to chase every additional order. Cities can provide protected cycle routes and designated collection areas, while restaurants should release orders when ready rather than forcing riders to make up time lost waiting inside.', 'the problem cannot be solved by telling riders to be careful while rewarding speed above everything else; safer incentives, income protection and practical infrastructure must work together.'],
  ['school-water-fountains', 'Limited drinking water at school', 'Education and health', 'Some schools do not provide convenient access to safe drinking water throughout the day. What problems does this cause, and how can they be solved?', 'A basic facility can influence pupils’ comfort, concentration and choices about drinks.', 'Poor hydration and dependence on sugary drinks can be reduced through reliable water facilities and sensible classroom rules.', 'Pupils may avoid drinking if the nearest fountain is broken or far from their classroom. During hot weather or physical activity, headaches and discomfort can make attention harder. Buying bottled drinks creates a cost for families and unnecessary packaging, while vending machines may direct children towards sweet alternatives simply because they are easier to obtain.', 'Schools should install accessible refill points, test water quality and assign responsibility for repairs. Allowing suitable bottles in class makes the facility useful rather than requiring pupils to wait until breaks. Clear routines can manage spills, and teachers should model regular drinking. Funding must include maintenance, since an impressive installation offers little benefit if it stops working a few months later.', 'safe water should be treated as an essential everyday service, with access, upkeep and classroom practice coordinated instead of expecting pupils to overcome an avoidable obstacle themselves.'],
  ['elderly-heatwave', 'Protecting older residents during heatwaves', 'Health and cities', 'Longer heatwaves create difficulties for older people living alone in cities. What are the main problems, and what measures can reduce them?', 'Prolonged urban heat is particularly dangerous when a resident is isolated and unable to cool their home.', 'Health risks and social isolation require practical cooling assistance linked to dependable local support.', 'An older person may not recognise dehydration or may avoid opening a window because of security concerns. A top floor flat can remain hot overnight, removing the chance to recover. Isolation makes the danger worse: if a resident becomes confused or weak, nobody may notice promptly. High electricity costs can also discourage using available fans or cooling devices.', 'Local services should contact vulnerable residents during alerts and provide accessible cool spaces with transport where needed. Building improvements such as external shading and insulation reduce heat before emergency measures are necessary. Energy assistance can protect people afraid of unaffordable bills. Neighbours and care providers need a clear way to request help, rather than relying on a general warning that assumes everybody can act independently.', 'cooler housing and reliable personal contact are more protective than advice alone, because the people at greatest risk may lack the money, mobility or support needed to follow it.'],
  ['electronic-waste-storage', 'Unwanted electronics kept at home', 'Technology and environment', 'Many households keep broken electronic devices because they do not know how to dispose of them safely. What problems does this create, and what solutions can you suggest?', 'Unused electronics can accumulate in homes while valuable materials remain outside the recycling system.', 'Waste, safety and data concerns call for trusted collection services with clear disposal information.', 'Stored devices occupy space and may eventually be thrown into ordinary rubbish, where batteries can cause fires and materials are lost. Owners also worry that personal information remains on an old phone or computer. That concern can lead to indefinite storage even when a recycling point exists, so simple instructions about where to leave a device do not remove the main barrier.', 'Councils and retailers should offer convenient collection and explain which items they accept. Certified services can provide secure data erasure or allow owners to remove storage components first. Repair and donation should be considered before recycling, while damaged batteries need separate handling. Public information should describe the process plainly and show where materials go, helping people distinguish a responsible operator from an informal collector.', 'convenient disposal and confidence about personal data are both necessary; a trusted system can recover materials and reduce risks without asking households to become technical waste experts.'],
  ['new-workers-lonely', 'Isolation among new employees', 'Employment and wellbeing', 'New employees sometimes feel isolated when most of their colleagues work remotely. What problems can this cause, and how can employers address them?', 'Remote teams may operate smoothly for established staff while leaving a newcomer uncertain about everyday expectations.', 'Isolation can slow learning and weaken confidence, so intentional support is needed instead of expecting informal contact to happen online.', 'A new employee may hesitate to ask questions in a large group message, fearing that basic uncertainty will look incompetent. Without hearing ordinary workplace conversations, they can miss unwritten procedures and repeat avoidable mistakes. The result is not only loneliness but slower progress and early resignation, which imposes costs on both the individual and the organisation.', 'A named mentor, scheduled short check ins and a clear guide to common tasks provide dependable routes for questions. Teams can arrange occasional purposeful meetings that include informal time rather than filling the day with presentations. Newcomers should also be invited into relevant decisions and given feedback early. Support must be recognised as part of a colleague’s workload so it does not disappear during busy periods.', 'effective integration requires visible responsibility and regular, useful contact; simply adding a new worker to online channels does not reproduce the learning and reassurance available through everyday interaction.'],
  ['rural-school-teachers', 'Teacher shortages in remote schools', 'Education and regional development', 'Schools in remote areas often struggle to recruit and retain teachers. What problems result from this, and what solutions can be proposed?', 'Staff shortages can make a child’s educational opportunity depend heavily on where the family lives.', 'Interrupted learning and restricted subject choice require better employment conditions and professional support for remote teachers.', 'Frequent vacancies lead to classes taught by temporary staff who may not know pupils’ progress. A small secondary school can also lose an entire subject when its only specialist leaves. Students then have fewer qualifications available for further study, while existing teachers take extra duties and become more likely to leave, reinforcing the shortage.', 'Housing support and reliable transport can remove practical barriers to relocation, but salary supplements alone will not solve professional isolation. Remote teachers need mentoring, training access and manageable workloads. Recruiting local trainees with funded qualifications may create a more durable workforce. Digital teaching can supplement specialist lessons, yet it still requires on site support rather than serving as an excuse to leave schools understaffed.', 'retention should be treated as a package of living conditions, professional development and realistic duties, protecting pupils from repeated disruption rather than merely filling vacancies for a few months.'],
  ['polluted-school-air', 'Air pollution around schools', 'Health and environment', 'Children in some urban schools are exposed to high levels of air pollution. What problems does this cause, and what measures should be taken?', 'Children can be repeatedly exposed to traffic pollution while learning and playing in the same location.', 'Health risks and unequal exposure require action on local emissions as well as protection inside schools.', 'Polluted air can aggravate breathing problems and lead to missed lessons, especially for pupils who already have asthma. Schools beside major roads may serve communities with fewer resources to move or demand improvements. The burden is therefore educational and social as well as medical, because repeated illness can reduce participation and make existing inequalities harder to overcome.', 'Authorities should monitor local air and reduce vehicle idling, heavy traffic and dirty buses near school sites. Ventilation and suitable filtration can help indoors, but they should not replace emission reduction. Schools can schedule outdoor activity away from the worst periods while longer term measures are implemented. New school locations should be assessed for air quality instead of choosing cheap land without considering health costs.', 'children need cleaner surroundings, not merely instructions to remain indoors, so emission control and well maintained school buildings should be planned together.'],
  ['renting-unpredictable', 'Frequent moves in rented housing', 'Housing and society', 'Many families renting homes have to move frequently. What problems can this cause, and what solutions are available?', 'A home can be physically adequate yet fail to provide stability when occupation is repeatedly uncertain.', 'Frequent moves disrupt education and support networks, so tenancy security and sufficient affordable housing are essential.', 'Children may change schools midyear and lose friendships, while parents must rearrange journeys to work or childcare. Moving also consumes money through deposits, transport and time off, making it harder to save for more stable housing. A household can therefore remain trapped in insecurity even when it pays rent reliably and has caused no problem to the property owner.', 'Longer default tenancy periods and clear, lawful grounds for ending them would reduce avoidable disruption. Rent assistance needs predictable eligibility, and investment in affordable homes must address the shortage behind repeated competition. Landlords still require a workable route to recover property in legitimate circumstances, but notice periods should give families enough time to find another suitable home rather than force rushed, costly decisions.', 'greater tenancy security should accompany housing supply, because families need both an available place to live and a reasonable expectation that responsible occupation will not end without adequate warning.'],
  ['tourist-litter-coast', 'Waste in seasonal coastal towns', 'Tourism and environment', 'Coastal towns receive large amounts of litter during the tourist season. What problems arise, and how can they be reduced?', 'A small coastal town may need to manage a summer population far larger than its permanent community.', 'Pollution and pressure on local services require seasonal capacity planning and shared responsibility for waste.', 'Overflowing bins allow plastic and food packaging to reach beaches and the sea, where they can harm wildlife. Residents then experience smells and damaged public spaces while ordinary collection schedules remain designed for a much smaller population. Poor conditions can also undermine the town’s appeal, so the waste affects both the environment and the income tourism is meant to bring.', 'Collection should increase during predictable peaks, with well placed covered bins and facilities for sorting waste. Accommodation providers and food sellers can reduce unnecessary packaging and explain local disposal rules. A modest visitor levy may help fund seasonal services if its purpose is transparent. Enforcement should target repeated dumping, while facilities make responsible behaviour straightforward rather than merely telling visitors to take everything away.', 'seasonal tourism must pay for the services it requires, combining adequate facilities and lower waste generation so that residents and coastal ecosystems do not absorb all the costs.'],
  ['eldercare-burnout', 'Stress among family carers', 'Health and family', 'Adults caring for elderly relatives at home often experience severe stress. What problems does this create, and what support would help?', 'Home care can depend on one family member performing demanding tasks with little rest or training.', 'Carer exhaustion threatens both wellbeing and care quality, so respite and practical support should be treated as essential services.', 'A relative may combine paid work with washing, medication and night time supervision. Exhaustion can damage their health, reduce earnings and increase the likelihood of mistakes, even when they are deeply committed to the older person. Feeling unable to leave the house also weakens friendships and makes it harder to ask for help before a crisis develops.', 'Regular respite care gives families a predictable break rather than assistance only after collapse. Training on lifting, medication routines and available benefits can prevent avoidable difficulties. Employers can offer flexible hours, while local care coordinators help families navigate services. Support should respect the older person’s preferences and provide continuity, since an unfamiliar substitute who arrives without preparation may create additional anxiety.', 'sustainable family care requires rest, skills and dependable backup, recognising that commitment cannot indefinitely replace the professional support needed to keep both carers and relatives safe.'],
  ['digital-homework-access', 'Homework requiring constant internet access', 'Education and inequality', 'Schools increasingly set homework that requires reliable internet access. What problems can this create, and how can they be solved?', 'Online homework can quietly assume that every pupil has the same resources at home.', 'Unequal access and competing household demands can distort achievement, so schools need accessible alternatives and practical support.', 'A pupil sharing one phone with siblings may understand a lesson but be unable to complete the assignment on time. Unstable connections can also prevent uploading work, making a technical problem appear to be poor motivation. Parents who cannot afford data or understand the platform may struggle to help, so existing disadvantage is reinforced by the method used to assess learning.', 'Schools should check access confidentially, lend suitable devices and provide tasks that can be downloaded or completed offline. Supervised study sessions offer another route, but their timing must suit transport and family responsibilities. Teachers should accept equivalent formats when necessary and avoid penalties for documented access failures. Long term connectivity support is valuable, yet immediate assessment must remain fair while that infrastructure develops.', 'digital learning should expand opportunity rather than measure household technology, with equivalent routes to completing work and support that reaches pupils without publicly labelling them as disadvantaged.'],
  ['wildfire-insurance', 'Housing insecurity after wildfires', 'Environment and housing', 'In areas affected by repeated wildfires, some households can no longer obtain affordable home insurance. What problems does this create, and what solutions can you suggest?', 'Repeated disasters can make protection against the next loss too expensive for ordinary households.', 'Financial vulnerability and declining property security require risk reduction alongside carefully limited public insurance support.', 'Without insurance, a family may lose both its home and savings after a fire. Lenders may refuse mortgages, while homeowners already living in the area find it difficult to sell and move. The resulting uncertainty affects the wider community: repairs are delayed, investment falls and poorer households face the greatest pressure to remain in a dangerous location.', 'Authorities should improve evacuation planning, manage nearby vegetation and enforce suitable building standards. A public insurance arrangement could protect existing vulnerable residents, but it should not subsidise unlimited new construction in high risk zones. Voluntary relocation support may be appropriate where protection is unrealistic. Clear risk maps and planning decisions are necessary so that financial assistance does not encourage the same exposure to grow.', 'insurance support can prevent immediate hardship, but long term safety depends on reducing exposure and offering alternatives where repeated rebuilding would leave families and public budgets permanently at risk.'],
  ['festival-noise', 'Large festivals near residential areas', 'Culture and community', 'Large music festivals are sometimes held close to residential neighbourhoods. What problems can this cause, and how should they be addressed?', 'A festival brings cultural activity and visitors, but its effects extend beyond the ticket holders.', 'Noise, congestion and temporary disruption need predictable limits and direct coordination with residents.', 'Late night sound can disturb sleep, particularly for people who work early or have young children. Traffic and parked vehicles may block ordinary access, while litter remains after visitors leave. Residents receiving little direct benefit can feel that their neighbourhood has been handed over to an event organiser, turning a celebration into a recurring source of resentment.', 'Permits should specify ending times, sound monitoring and a plan for transport, cleaning and emergency access. Organisers can provide a contact who resolves problems during the event rather than asking residents to complain afterward. Consultation should occur before dates and layouts are fixed. Occasional events with clear benefits may be acceptable, but repeated disruption needs tighter limits or a more suitable site.', 'festivals can coexist with residential life only when their organisers accept responsibility for the surrounding area, with enforceable conditions rather than vague promises that the disturbance will be temporary.'],
  ['online-returns-waste', 'Waste from frequent online shopping returns', 'Consumption and environment', 'Large numbers of goods bought online are returned to sellers. What problems does this cause, and how can the situation be improved?', 'The convenience of returning a purchase can hide the resources required to transport and process it again.', 'Excessive returns create emissions and waste, so better information and responsible processing are needed without removing legitimate consumer protection.', 'An item may travel twice and require additional packaging, while some low value products are discarded because inspection costs more than replacement. Ordering several sizes with the intention of returning most of them multiplies this activity. The waste is especially concerning when shoppers cannot see that an unopened product may still fail to return to ordinary sale.', 'Retailers should provide accurate measurements, clear photographs and reliable product descriptions, reducing mistakes before purchase. They can consolidate collection and resell suitable returns transparently instead of destroying them. Customers should retain free remedies for faulty or misleading goods, while repeated discretionary bulk returns can face proportionate conditions. A clear distinction prevents environmental concerns from becoming an excuse for selling poor products without accountability.', 'returns policy should protect buyers from genuine faults while reducing avoidable journeys and disposal, using better information and recovery systems rather than an indiscriminate ban on sending goods back.'],
  ['urban-public-toilets', 'A shortage of public toilets', 'Cities and health', 'Many city centres have too few clean public toilets. What problems does this create, and what solutions can be proposed?', 'A basic public facility can determine whether someone is able to spend time outside the home.', 'The shortage restricts access and damages public health, so reliable provision and maintenance should be part of city planning.', 'Older people, pregnant women and those with medical conditions may avoid a trip if they cannot find a toilet. Parents can also be forced to buy something in a café simply to obtain access. In busy areas, the shortage contributes to unhygienic conditions and places extra demands on private businesses, showing that the problem extends beyond personal inconvenience.', 'Councils should map demand near transport hubs, markets and parks, then fund cleaning and repairs as well as construction. Agreements with suitable businesses can supplement public facilities, provided access is clearly marked and does not require a purchase. Accessible design and safe opening hours are essential. Real time information is helpful, but a website cannot compensate for a locked or unusable building.', 'public toilet access deserves dependable funding because it enables participation in city life, and success should be judged by cleanliness, accessibility and actual opening rather than the number of facilities listed.'],
  ['school-exam-stress', 'Stress before high stakes examinations', 'Education and wellbeing', 'Students experience increasing stress before important school examinations. What problems can this cause, and what measures could reduce it?', 'An examination can become overwhelming when students believe one result will determine their entire future.', 'Sleep loss and narrow learning require realistic assessment systems and practical preparation, not merely advice to relax.', 'Anxiety can lead pupils to study late into the night, reducing the concentration they need the next day. Some avoid difficult subjects because they fear mistakes, while others memorise predicted answers rather than build understanding. Pressure from adults can make seeking help feel like admitting failure, so a student may conceal distress until both health and performance deteriorate.', 'Schools should teach manageable revision planning and provide confidential support early. Assessment spread across several tasks can reduce dependence on one day, provided that it does not create a constant stream of minor deadlines. Parents need accurate information about alternative routes into further study. Practice exams should be used to identify learning needs rather than publicly rank pupils in a way that amplifies fear.', 'preparation and support matter, but reducing the sense of irreversible failure also requires assessment and progression routes that acknowledge students’ abilities more broadly than a single result.'],
  ['battery-fire-disposal', 'Discarding rechargeable batteries safely', 'Technology and public safety', 'Rechargeable batteries are often thrown into ordinary household rubbish. What problems does this cause, and how can this behaviour be changed?', 'A small discarded battery can become a serious hazard when it is crushed among other waste.', 'Fire risk and lost materials require convenient collection and unmistakable disposal guidance.', 'Damaged batteries may ignite inside a collection vehicle or sorting facility, endangering workers and interrupting waste services. Valuable metals are also lost when batteries enter general rubbish. The danger is not obvious to someone who sees a battery as an ordinary small object, especially when it is hidden inside a toy or household gadget.', 'Products should show a clear battery symbol and simple removal instructions where safe removal is possible. Shops and local centres can provide collection points, with staff trained to handle damaged items separately. Public messages should explain the crushing and fire mechanism rather than only ask people to recycle. Manufacturers should also design devices so that battery replacement and eventual disposal are not unnecessarily difficult.', 'safer disposal depends on making the risk understandable and the alternative easy, while product design should support that behaviour instead of concealing batteries inside items destined for ordinary rubbish.'],
  ['campus-food-cost', 'Students struggling with meal costs', 'Education and health', 'Some university students cannot afford regular nutritious meals. What problems arise from this, and what can universities do to help?', 'Financial hardship can affect the most basic conditions needed to benefit from higher education.', 'Poor nutrition and reduced participation require affordable provision that students can use without embarrassment.', 'A student skipping meals may find long laboratory sessions or evening study difficult, and taking additional paid shifts can leave less time to learn. Financial anxiety may also discourage social contact built around eating together. This creates an unequal university experience in which admission is technically open but some students struggle to meet the daily conditions required for success.', 'Universities can provide low cost nutritious meals, emergency grants and communal kitchens in accommodation. Assistance should be easy to request, with clear eligibility and prompt decisions. Contracts with campus food providers can include an affordable meal option throughout teaching hours. Sharing information about budgeting may help, but it cannot replace financial support when income is genuinely insufficient to cover food.', 'affordable meals and timely assistance protect both health and educational opportunity, recognising that students cannot solve a structural shortfall simply by managing an inadequate budget more carefully.'],
];

const causes: Plan[] = [
  ['late-night-sleep', 'Adults going to bed later', 'Health and lifestyle', 'Many adults regularly go to bed later than they intend. Why does this happen, and what can be done about it?', 'Bedtime is often delayed even when people know that they need more sleep.', 'Competing demands and attention capturing media explain much of the pattern, so both routines and wider expectations should change.', 'For someone who spends the day working and caring for others, late evening may feel like the only personal time available. Entertainment platforms then make stopping difficult by automatically continuing content. A planned short break becomes another hour awake, while the next morning’s obligations remain unchanged. The behaviour is therefore not always a lack of knowledge about the value of rest.', 'A realistic evening routine should protect some enjoyable time before the intended bedtime, rather than rely entirely on self denial. Turning off automatic playback and placing work messages outside the bedroom reduces immediate cues. Employers can also limit unnecessary late requests. Where shift patterns are the main cause, more predictable schedules matter more than advice directed at an individual’s phone habits.', 'better sleep requires reducing the pressures and incentives that keep people awake, combining personal boundaries with working arrangements that leave genuine time to recover.'],
  ['small-town-young-leave', 'Young people leaving small towns', 'Regional development', 'Young adults increasingly leave small towns and do not return. What are the causes, and how can this trend be addressed?', 'A move for study can become permanent when a young person sees no realistic future in the hometown.', 'Limited careers and services drive departure, so communities need opportunities rather than campaigns asking young people to stay loyal.', 'Universities and specialised employers are usually concentrated elsewhere. After completing a degree, a graduate may find that the only local openings do not use the new qualification. Limited rental housing and poor transport add to the difficulty of returning, even when family ties remain strong. Leaving can therefore be a rational response to a narrow range of practical choices.', 'Regional investment should support diverse businesses, apprenticeships and reliable digital connections. Affordable homes and transport to nearby employment centres make a return more feasible. Partnerships with colleges can provide training locally, while remote work hubs help people maintain professional contact. Authorities should consult young adults about actual barriers rather than assume that festivals or promotional slogans will substitute for a sustainable livelihood.', 'small towns retain residents when they offer viable adult lives, so employment, housing and connectivity should take priority over trying to persuade young people to accept fewer opportunities.'],
  ['takeaway-rising', 'Growing dependence on takeaway meals', 'Food and lifestyle', 'More households rely on takeaway meals instead of cooking at home. Why is this happening, and what effects does it have?', 'Food delivery has become an ordinary part of household routines rather than an occasional convenience.', 'Time pressure and easy ordering drive the change, with mixed consequences for health, budgets and shared skills.', 'Long journeys, irregular work and childcare can leave little energy to plan, shop and cook. Delivery apps remove several steps and present a meal as a quick decision, often reinforced by discounts. For a household without a suitable kitchen, convenience is not merely laziness. The ease of ordering also means that a habit can continue after the original time pressure has passed.', 'Takeaways can provide variety and help someone eat during a demanding period, but frequent orders may cost more and offer less control over salt, portions or ingredients. Cooking skills can weaken when they are rarely practised, and packaging increases household waste. The outcome depends on what is ordered and why, so occasional prepared meals should not be confused with permanent dependence on an expensive, nutritionally narrow routine.', 'the trend reflects real changes in time and access as well as marketing, and its effects are most concerning when convenience gradually replaces affordable, varied meals and the ability to prepare them.'],
  ['language-dialect-loss', 'Regional dialects becoming less common', 'Language and culture', 'Some regional dialects are used less often by younger people. Why is this happening, and how can these dialects be preserved?', 'Young speakers may understand a regional dialect while choosing not to use it in everyday conversation.', 'Mobility and social pressure encourage dominant speech, so preservation should increase the dialect’s usefulness and status.', 'School, national media and employment often reward a standard form of speech. A teenager may also fear being judged as provincial when meeting people from elsewhere, especially online. Families then use the standard language to support educational success, unintentionally reducing opportunities for children to practise the local variety. The change can occur without anyone consciously deciding that the dialect should disappear.', 'Schools can welcome local speech in oral history projects while still teaching the standard language needed for wider communication. Regional broadcasting, storytelling and music give young people contemporary reasons to use it. Recording older speakers preserves evidence, but living use matters more than an archive alone. Public figures who speak the dialect confidently can also challenge the assumption that it signals limited education.', 'preservation should add opportunities rather than restrict standard language learning, allowing young people to communicate widely without feeling that their regional voice is something to hide.'],
  ['delayed-parenthood', 'Starting families later in life', 'Family and society', 'People in many countries are having their first child later in life. What are the causes, and what are the consequences?', 'The timing of parenthood increasingly depends on a long period of preparation rather than an early adult expectation.', 'Education, insecure work and housing costs contribute to delay, bringing both greater readiness and new challenges.', 'Longer study and temporary jobs can make stable income arrive later. Couples may also postpone children until they can rent a suitable home or obtain affordable childcare. Improved control over reproduction allows these decisions to be intentional. Personal aims, such as travel or career development, matter too, but a delay should not always be interpreted as a simple preference when material barriers constrain the choice.', 'Later parents may bring financial stability and clearer expectations to raising a child. However, delay can reduce the time available to have additional children and can create health or fertility challenges, although individual circumstances vary. Grandparents may also be older when practical help is needed. At the population level, a sustained shift can affect age balance and the future demand for schools and care services.', 'later parenthood combines chosen preparation with economic constraints, and policy should support genuine choice through housing and childcare rather than assume that everybody delays for the same reason.'],
  ['public-bus-decline', 'Declining bus use outside cities', 'Transport and regions', 'Bus use is falling in some rural and suburban areas. Why is this happening, and how can it be reversed?', 'A local bus network can decline through a cycle in which fewer passengers lead to an even less useful service.', 'Unreliable coverage and car dependent development are central causes, requiring coordinated improvements rather than isolated fare discounts.', 'If the last bus leaves before work ends, passengers need another way home and may stop using the service altogether. Shops and housing built far from existing routes reinforce this dependence on cars. Operators then cut frequencies because passenger numbers are low, making the bus still less attractive. Existing demand statistics can conceal people who would travel if the timetable were usable.', 'Authorities should coordinate routes with major workplaces, schools and connecting trains. A dependable basic frequency, clear information and integrated tickets can rebuild confidence. Smaller demand responsive vehicles may serve scattered settlements, while new developments should be planned around transport access. Subsidies need stable commitments, because a brief improvement that disappears after a trial does not persuade a household to reconsider owning a car.', 'reversing decline requires a service that fits real journeys and remains dependable, alongside land use decisions that prevent the next generation of homes and jobs from being inaccessible without driving.'],
  ['newspaper-local-loss', 'Local newspapers losing readers', 'Media and society', 'Local newspapers are losing readers and income in many places. What are the causes, and what effects does this have on communities?', 'The decline of a local newspaper can remove a source of reporting that national media rarely replace.', 'Changing advertising and reading habits explain the financial pressure, while reduced local scrutiny is a serious consequence.', 'Advertisers can now reach customers through online platforms without buying space in a newspaper. Readers also expect quick updates on phones and may see links without paying for the reporting behind them. A local publication has fewer subscribers to spread the fixed cost of covering courts or council meetings, so the loss of even modest advertising income can force staffing cuts.', 'Communities may then receive less independent information about planning decisions, public spending and local services. Rumours can circulate widely when nobody is routinely checking claims or asking officials questions. New online outlets can fill part of the gap, but they also need dependable funding and professional standards. The issue is therefore not preserving paper itself; it is maintaining original reporting that holds nearby institutions accountable.', 'the business model has weakened as attention and advertising move online, and the most damaging effect is the loss of verified local knowledge rather than the disappearance of a particular printed format.'],
  ['children-less-outdoors', 'Children spending less time outside', 'Childhood and health', 'Children spend less time playing outdoors than in the past. Why is this happening, and what can be done to encourage outdoor play?', 'Outdoor play competes with attractive indoor activities and with the way neighbourhoods are organised.', 'Screen entertainment and concerns about safety contribute, so encouragement must include suitable places rather than rely only on parents’ rules.', 'Games and videos offer predictable stimulation at home, while outdoor space may require adult supervision or a journey. Busy roads and a lack of nearby parks make parental caution understandable. Scheduled lessons can also fill the hours formerly available for free play. These pressures reinforce each other, making staying inside the easiest option even when a child enjoys physical activity.', 'Safer crossings, traffic calming and well maintained local play areas lower practical barriers. Schools can protect outdoor breaks and offer varied activities rather than only competitive sport. Parents can create regular opportunities with other families, giving children companionship and adults confidence. Digital limits may help, but they are more effective when an appealing alternative is close, affordable and available at the times families need it.', 'outdoor play becomes more likely when safe space and free time are protected, so changing the environment is as important as asking children to choose it over a screen.'],
  ['cheap-furniture-waste', 'Replacing furniture more frequently', 'Consumption and environment', 'People increasingly replace furniture after only a short period of use. Why is this happening, and what environmental effects does it have?', 'Furniture once expected to last for years is now sometimes treated as a temporary purchase.', 'Low upfront prices, changing styles and difficult repairs encourage replacement, increasing waste and resource demand.', 'Flat pack products make furnishing a home quickly more affordable, but some designs are difficult to repair after a joint or panel breaks. Online trends also encourage a new appearance before the old furniture is worn out. For renters moving between differently sized rooms, replacement may seem easier than transporting heavy pieces, especially when storage and removal services are costly.', 'Frequent disposal increases demand for timber, metals and plastics and adds bulky items to waste systems. A usable desk may still be discarded if selling or donating it is inconvenient, so the impact extends beyond genuinely broken objects. Durable modular designs, available spare parts and easy collection for reuse would reduce harm. The environmental comparison should include product life and transport, not just whether one material looks natural.', 'rapid replacement reflects both design and household circumstances, and its environmental cost is greatest when repairable or usable furniture becomes waste because longevity and reuse were never made convenient.'],
  ['water-groundwater', 'Overuse of underground water', 'Agriculture and environment', 'Underground water reserves are falling in some agricultural regions. What causes this, and how can the problem be addressed?', 'Groundwater can appear dependable until extraction exceeds the rate at which the reserve is replenished.', 'Water intensive farming and weak control of pumping require better incentives and management that protect farmers’ livelihoods.', 'A grower may respond to uncertain rainfall by drilling a deeper well, while subsidised electricity makes pumping cheaper than conserving water. If neighbouring farms do the same, each individual decision seems reasonable but the shared reserve declines. Crops selected for market value rather than local conditions can intensify the pressure, and the damage remains hidden until wells begin to fail.', 'Authorities need reliable measurement and enforceable extraction limits, developed with farmers rather than announced without alternatives. Support for suitable crops, efficient irrigation and soil moisture retention can reduce demand. Electricity pricing should not reward unlimited pumping, but abrupt cost increases can harm small farms. Transitional assistance and shared monitoring help align individual decisions with the long term survival of the water source.', 'the reserve can recover only when total extraction is controlled, and conservation will be more durable if farmers receive practical ways to earn a living within that limit.'],
  ['teens-books-less', 'Teenagers choosing shorter reading', 'Education and media', 'Many teenagers read fewer long books and more short online texts. Why is this happening, and what are the consequences?', 'The format of everyday reading has changed as short messages and recommendations become constantly available.', 'Convenience and immediate feedback favour short texts, with consequences for sustained attention and the kinds of ideas readers encounter.', 'Online platforms offer material that can be finished in a spare moment, followed immediately by another recommendation. A long book asks for a larger commitment without the same visible social rewards. Heavy school workloads may leave teenagers wanting quick relaxation rather than demanding reading. This does not mean they dislike all reading, but the environment makes a short text the easier default choice.', 'Short texts can introduce useful information and diverse voices, yet they may provide less opportunity to follow a complex argument or a slowly developing character. Readers can also rely on summaries without questioning what has been omitted. Schools and libraries should connect young people with engaging, varied books and protect time to read them, avoiding the assumption that only a narrow list of difficult classics has value.', 'the trend reflects the incentives of digital life rather than a complete rejection of reading, but sustained reading still deserves support because some forms of understanding cannot be developed through fragments alone.'],
  ['food-price-volatility', 'Unstable prices of basic foods', 'Food and economics', 'The prices of basic foods have become less predictable in some countries. What are the causes, and what effects does this have on households?', 'A household budget is harder to manage when essential food costs change suddenly.', 'Climate disruption and supply costs contribute to volatility, with the strongest effects falling on families whose spending is already concentrated on necessities.', 'Droughts or floods can reduce harvests while fuel and fertiliser costs affect production and transport. Dependence on a small number of suppliers makes a disruption harder to absorb. Retail prices may therefore change even when local demand remains steady. Households cannot easily distinguish these supply pressures from pricing decisions, which can increase uncertainty about how long a rise will last.', 'Low income families may switch to cheaper, less varied meals or reduce spending on healthcare and education. A sudden rise also makes saving and debt repayment more difficult. Better storage, diversified supply and transparent market information can reduce some instability, while targeted assistance protects basic nutrition. General subsidies need caution because they may be costly without reaching the households most exposed to the change.', 'food price volatility combines environmental and economic pressures, and its social impact depends on whether vulnerable households have reliable assistance rather than being forced to absorb every unexpected increase alone.'],
  ['women-engineering-barrier', 'Unequal participation in engineering', 'Education and equality', 'In some countries, women remain underrepresented in engineering courses and careers. What are the causes, and how can participation be improved?', 'Unequal participation can develop long before a student submits a university application.', 'Stereotypes and unequal access to encouragement contribute, so action must address education and workplace conditions rather than blame individual preferences.', 'Children may see engineering toys, examples and career advice presented mainly to boys. A girl interested in mathematics can receive less encouragement or meet few visible role models, making the field seem socially distant. Later, accounts of unwelcoming workplaces and limited progression can affect course choices. These barriers do not mean every woman wants the same career, but they can narrow the choices she considers realistic.', 'Schools should offer practical engineering activities to all pupils and review guidance for hidden assumptions. Mentoring and visible examples of varied careers can make the possibilities concrete. Employers also need fair recruitment, effective responses to harassment and progression arrangements compatible with caregiving. Scholarships may improve entry, but lasting participation depends on a workplace where trained women can remain and advance.', 'participation improves when interests can develop without artificial discouragement and careers offer fair conditions, so widening access and improving retention should be treated as connected tasks.'],
  ['city-noise-rise', 'Cities becoming noisier', 'Cities and health', 'Noise levels are increasing in many cities. What are the main causes, and what measures can reduce the problem?', 'Urban noise accumulates from activities that are useful individually but disruptive when concentrated in the same place.', 'Traffic, construction and poorly managed evening activity are important causes, requiring planning and enforcement rather than a single ban.', 'More delivery vehicles and motorcycles create repeated short bursts of sound throughout the day, while dense construction exposes nearby residents for long periods. Restaurants and entertainment venues may add music and departing crowds at night. Buildings with poor insulation allow these sounds to interrupt sleep even when a resident has closed the windows, making the effect more serious than a brief annoyance.', 'Quieter road surfaces, vehicle standards and better public transport can reduce traffic noise at its source. Construction permits should include reasonable hours and mitigation, while entertainment licences need clear limits and responsive complaint procedures. Building standards must also consider acoustic insulation. Enforcement should identify recurring sources rather than merely ask residents to tolerate noise as an unavoidable sign of a lively city.', 'noise can be reduced by coordinating transport, building design and activity rules, protecting rest without assuming that all business or public life must stop.'],
  ['social-media-status', 'Buying products to display status online', 'Consumption and media', 'Some people buy expensive products mainly to show them on social media. Why does this happen, and what effects can it have?', 'Online visibility can turn a private purchase into a performance for an audience.', 'Comparison and commercial promotion encourage status buying, which can distort both spending and self worth.', 'A feed presents selected images of other people’s lives without showing debts, sponsorship or ordinary limitations. Repeated exposure can make a luxury item appear normal or necessary for acceptance. Influencers also blur the boundary between personal recommendation and advertisement. Buying something visible then offers a quick route to attention, even if the owner has little practical use for it.', 'The immediate result may be debt or reduced spending on genuine needs. Approval is often temporary, encouraging another purchase when the first no longer attracts attention. People can also judge others by displayed possessions, weakening relationships based on less visible qualities. Clear advertising labels and financial education help, but individuals need space to recognise that an edited online comparison is not a reliable measure of a successful life.', 'status purchases are reinforced by curated comparison and marketing, and their harm is greatest when temporary online recognition begins to direct financial decisions and the way people value themselves.'],
  ['migrant-skills-unused', 'Qualified migrants working below their skill level', 'Employment and migration', 'Some migrants cannot find work matching their professional qualifications. What causes this, and how can the situation be improved?', 'Moving country can make a previously useful qualification difficult for employers or regulators to evaluate.', 'Recognition barriers and limited local networks explain much of the mismatch, so fair assessment and targeted transition support are needed.', 'An employer may be uncertain about a foreign course, while a regulated occupation requires evidence that is costly or slow to obtain. A newcomer also lacks local references and knowledge of recruitment conventions. As savings decline, they may accept work unrelated to their training, then find it harder to demonstrate current professional experience when an appropriate vacancy appears.', 'Clear recognition procedures should explain requirements, costs and expected timelines. Bridging courses can address specific gaps without forcing a qualified person to repeat an entire degree. Supervised placements, language support for professional tasks and fair assessment of overseas experience help employers judge competence. Safety standards must remain, but they should distinguish genuine differences in preparation from unnecessary administrative obstacles.', 'matching migrants to their skills benefits both individuals and the receiving society, and transparent verification is more effective than treating unfamiliar qualifications as automatically inadequate.'],
  ['exercise-gym-dropout', 'Abandoning exercise programmes', 'Health and lifestyle', 'Many people begin an exercise programme but stop after a short time. Why does this happen, and how can they be encouraged to continue?', 'Starting a programme is often easier than fitting it into ordinary life for months.', 'Unrealistic expectations and inconvenient routines cause many people to stop, so sustainable activity should take priority over dramatic early targets.', 'A beginner may choose demanding sessions based on rapid transformation promises. Soreness and slow visible progress then make the effort feel unsuccessful. Travel to a distant gym, changing work hours and care responsibilities add practical friction. If one missed session is interpreted as complete failure, a temporary interruption can become abandonment even though smaller, regular activity would still provide benefits.', 'Programmes should begin at a manageable level and offer flexible alternatives such as walking, home exercises or short sessions. Tracking improved comfort, stamina and consistency gives feedback beyond body appearance. Supportive groups can provide companionship without punishing missed days. Healthcare and workplace initiatives should also address safe local spaces and time, since motivation alone cannot solve every obstacle to being active.', 'continued exercise depends on an achievable routine and realistic signs of progress, so encouragement should help people adapt activity to their lives rather than demand perfect adherence to an ambitious plan.'],
  ['rural-medical-departure', 'Healthcare staff leaving rural areas', 'Health and regional development', 'Many trained healthcare workers leave rural areas for larger cities. What are the causes, and what solutions can be suggested?', 'A rural clinic may recruit staff but still lose them when professional and personal needs remain unmet.', 'Limited resources and career opportunities drive departure, requiring a retention strategy wider than short term recruitment bonuses.', 'A clinician without reliable equipment or specialist support can feel unable to provide the standard of care they were trained to deliver. Heavy on call duties and few chances for further study make the job harder to sustain. Family members may also lack suitable schools or employment, so leaving can reflect the needs of an entire household rather than a preference for city life alone.', 'Reliable supplies, manageable staffing and links to specialist teams would improve everyday work. Funded training, career progression and scheduled rotations can reduce professional isolation. Housing and family support also matter, while recruiting and educating local students may create stronger long term ties. Service requirements should be fair and time limited; coercion without acceptable conditions is unlikely to produce committed, stable care.', 'rural retention improves when staff can deliver good care and build a viable life, so investment in conditions and development is more durable than repeatedly paying people to fill the same vacancy.'],
  ['birthdays-commercial', 'Celebrations becoming more expensive', 'Family and consumption', 'Family celebrations are becoming more expensive and elaborate in some societies. Why is this happening, and what effects does it have?', 'A celebration can shift from marking a relationship to demonstrating what a household can afford.', 'Commercial promotion and social comparison encourage rising expectations, with consequences for budgets and the meaning of the occasion.', 'Businesses offer packages that present elaborate decoration and entertainment as the normal standard for a birthday or anniversary. Shared photographs then make the most impressive events visible to many other families. People may fear appearing uncaring if they choose something simpler, even when guests would value time together more than the extra spending. Expectations can rise without explicit agreement.', 'Some celebration businesses gain employment, and a special event can create enjoyable memories. However, families may take on debt or avoid inviting people because they cannot afford the expected display. Hosts also spend time managing details instead of enjoying the gathering. Recognising thoughtful, inexpensive customs helps preserve inclusion and reduces the assumption that affection is measured by the size of an event.', 'more elaborate celebrations reflect marketing and comparison rather than greater affection, and their value is weakened when financial pressure or competitive display overtakes the relationships being celebrated.'],
  ['academic-cheating-ai', 'Students submitting work they did not write', 'Education and technology', 'Schools report that some students submit assignments produced by automated writing tools. Why does this happen, and how can schools respond?', 'A tool that generates fluent text changes the temptation to avoid the difficult process of learning to write.', 'Assessment pressure and unclear rules encourage misuse, so schools need both explicit boundaries and tasks that reveal students’ own reasoning.', 'A student facing several deadlines may see generated text as a fast way to secure a mark, especially when assignments repeat familiar questions. Uncertainty about acceptable assistance also blurs the boundary between checking grammar and replacing the argument. If the final document is the only evidence assessed, a learner can appear successful without understanding the ideas presented.', 'Schools should state which uses are permitted and require disclosure of substantial assistance. Draft discussions, oral explanations and in class stages make the learning process visible without relying entirely on unreliable detection software. Teachers can design tasks tied to specific class material or personal reasoning. Support for planning and writing is also necessary, since punishment alone does not address overload or the fear of producing imperfect work.', 'a credible response combines clear rules, process based assessment and teaching support, allowing useful technology where appropriate while ensuring that the student remains responsible for the thinking being evaluated.'],
];

const twoPart: Plan[] = [
  ['adult-language-classes', 'Learning another language in later life', 'Education and lifestyle', 'More retired people are attending foreign language classes. Why might they choose to do this? What benefits can it bring?', 'Language learning is increasingly an activity people begin for personal reasons after leaving work.', 'Travel and curiosity help explain the choice, while structured learning can bring useful social and practical benefits.', 'Retirement may provide time for an interest repeatedly postponed during employment. Someone hoping to visit relatives abroad can want more independence than a phrasebook offers, while another learner may enjoy films or literature from a different culture. Unlike a compulsory school subject, the class can be chosen around a meaningful goal, making the effort worthwhile even without an examination or career advantage.', 'Regular classes create contact with other people and a reason to prepare between meetings. Learners practise listening carefully, recalling vocabulary and accepting mistakes in a supportive setting. Practical language skills can also make travel more confident and personal. These are benefits of engagement rather than a guarantee against illness, and courses should suit different abilities instead of assuming every retired person learns at the same pace.', 'people often begin for travel or an unfinished interest, and the greatest benefits combine practical independence with continued learning and social connection rather than a certificate alone.'],
  ['park-paid-activities', 'Commercial activities in public parks', 'Cities and public space', 'Public parks increasingly host paid exercise classes and organised events. Why has this become common? Should these activities be limited?', 'A public park can be attractive to organisers because it offers space without the cost of an indoor venue.', 'Demand for outdoor activities explains the growth, but limits are necessary to preserve ordinary free access.', 'Exercise providers can offer a pleasant setting and avoid renting a studio, while customers enjoy fresh air and social contact. Councils may welcome organised activity because it encourages use and can generate income. An occasional class can therefore add value. The difficulty arises when popular areas are repeatedly occupied as if a public lawn were a private business facility.', 'Permits should limit group size, noise and the amount of space reserved, with higher scrutiny for events that require barriers or equipment. Local residents must still be able to walk, sit and play without paying or negotiating access. Fees can contribute to maintenance, but they do not justify turning the park’s main purpose into commercial rental. A clear timetable helps prevent conflicts between different users.', 'outdoor demand and lower costs encourage these activities, but proportionate limits should protect the park as a shared public resource rather than a venue available mainly to paying customers.'],
  ['financial-school-lessons', 'Teaching teenagers about money', 'Education and finance', 'Schools increasingly teach students how to manage personal finances. Why is this considered important? What should such lessons include?', 'Young people encounter financial choices before they necessarily understand the terms and risks involved.', 'Early financial independence makes this teaching important, and lessons should focus on practical judgement rather than promote particular products.', 'A teenager can purchase online, use instalment offers or sign a phone contract while having little experience of interest and recurring charges. Mistakes made early can create obligations that last beyond the original purchase. Schools provide a shared foundation, especially for pupils whose families cannot confidently explain the system. The aim should be to ask good questions rather than imply that careful budgeting can overcome every low income.', 'Lessons should include comparing total borrowing costs, reading basic contracts, planning for irregular expenses and recognising fraud. Students could analyse a realistic monthly budget or examine how a small subscription accumulates over time. They also need to know consumer rights and where impartial help is available. Digital security and pressure from advertising deserve attention because financial decisions are increasingly made through persuasive online interfaces.', 'financial education matters because everyday choices can have lasting consequences, and practical examples, rights and critical judgement are more useful than abstract arithmetic or advice to buy a specific account.'],
  ['public-screens-adverts', 'Advertising screens in public places', 'Media and cities', 'Large digital advertising screens are becoming common in public places. Why is this happening? Is it a positive or negative development?', 'Digital screens turn parts of the street into flexible advertising space that can change throughout the day.', 'Commercial demand explains their spread, but I regard uncontrolled expansion as a negative development.', 'Screen operators can sell several advertisements in the space once occupied by one poster and adjust messages for different times. Property owners gain income, while councils may accept screens as part of a contract funding shelters or street furniture. These incentives explain the growth, but they do not establish that residents receive benefits equal to the commercial return.', 'Bright, moving displays can distract road users and reduce the visual calm of a shared environment. Continuous energy use and night time light also create costs that an ordinary poster does not impose. Screens can provide useful emergency information, yet that function should not justify unrestricted advertising. Limits on brightness, location and operating hours would preserve essential information while preventing commercial competition from overwhelming public space.', 'the screens spread because they generate flexible advertising income, but without strict design and placement rules their distraction, light and energy costs make the development more harmful than beneficial.'],
  ['food-worldwide', 'Finding international food everywhere', 'Food and globalisation', 'Foods from many different countries are now available in ordinary supermarkets. Why has this happened? Is this a positive development?', 'A routine shopping trip can now include ingredients that previously required a specialist shop or overseas journey.', 'Trade, migration and changing tastes explain this variety, which is broadly positive if access and sustainability remain part of the discussion.', 'Improved transport and distribution make distant products easier to stock, while migrant communities create demand and introduce dishes to neighbours. Travel and cooking programmes also encourage customers to try unfamiliar ingredients. Once enough shoppers recognise a product, a supermarket can buy it in larger quantities and lower its price, reinforcing the change from unusual luxury to ordinary shelf item.', 'Greater choice can help people maintain cultural traditions and learn about others through cooking. It also gives households alternatives when a local product is unavailable. However, transporting perishable foods long distances can use substantial resources, and imported novelty should not automatically displace suitable seasonal produce. Clear origins and realistic prices help consumers make informed choices rather than assume that every global ingredient is equally necessary or sustainable.', 'international variety enriches everyday food and reflects interconnected communities, while attention to seasonality and sourcing can preserve those benefits without treating unlimited year round imports as cost free.'],
  ['retirement-volunteering', 'Volunteering after retirement', 'Society and community', 'Many people begin volunteering after they retire. Why do they do this? How can communities make better use of their contribution?', 'Retirement can release time and experience that a community has previously been unable to access.', 'People often seek purpose and connection, and organisations should offer flexible, meaningful roles with adequate support.', 'Leaving paid work may remove a routine and a source of social contact. Volunteering allows a person to continue using skills without the same career obligations, whether through helping with accounts, repairing equipment or supporting a local reading group. Some also want to contribute to a service they once relied on. Motivation is therefore wider than simply having nothing else to do.', 'Organisations can match roles to interests and physical abilities rather than assume every retiree wants the same task. Clear training, reasonable hours and reimbursement of expenses make participation more inclusive. Volunteers should not be expected to replace essential paid staff without support. Recognising their judgement and offering a way to suggest improvements is also more respectful than treating them as an unlimited supply of free labour.', 'purpose and social connection help explain volunteering, while communities gain most when they offer suitable roles, practical support and genuine respect for the experience retirees choose to contribute.'],
  ['career-switches', 'Changing career more than once', 'Employment and education', 'People increasingly change to a different career more than once during their working lives. Why is this happening? What preparation is needed to make such changes successful?', 'A working life no longer always follows one occupation from qualification to retirement.', 'Economic change and personal priorities encourage career shifts, which require realistic information and opportunities to develop transferable skills.', 'Technology can reduce demand for familiar tasks while creating new roles, making a change necessary rather than optional. People may also discover that their original career does not suit family commitments or personal interests. Longer working lives allow time for a second direction, but the desire for change should not be confused with certainty that an unfamiliar occupation will solve every difficulty.', 'Preparation should include understanding entry requirements, likely income and the daily reality of the new work. Short practical experience or conversations with workers can challenge idealised impressions. Training needs to build on existing skills where possible, while savings or transitional support reduce the risk of accepting unsuitable work under immediate financial pressure. Employers should assess relevant experience rather than treat all career changers as complete beginners.', 'career changes reflect both shifting demand and changing lives, and they succeed more often when evidence, targeted learning and financial planning replace an impulsive response to dissatisfaction.'],
  ['heritage-experience-travel', 'Travelling to understand history', 'Culture and tourism', 'Some people travel to historic places rather than learn about them only through books or films. Why do they do this? What can be learned from such visits?', 'A historic place offers a physical scale and setting that a description cannot fully reproduce.', 'Visitors seek a more tangible connection with the past, and thoughtful visits can deepen understanding of everyday life and historical decisions.', 'Standing inside a fort or walking through an old industrial district helps someone imagine distances, materials and working conditions. The atmosphere can also create an emotional connection that motivates further learning. However, the desire for an authentic experience does not guarantee one, because restored buildings and commercial displays may present a selective version of the place.', 'Good interpretation can show how people used the site and how its meaning changed over time. A visitor may notice the relation between a settlement and its river, for example, understanding why trade developed there. Guides should explain uncertainty and include perspectives beyond famous leaders. Combining observations with reliable written sources produces more insight than collecting photographs or assuming that everything visible is original.', 'people travel for a tangible encounter with the past, and the educational value lies in connecting physical evidence to carefully explained context rather than treating presence at the site as understanding by itself.'],
  ['balcony-gardens', 'Gardening in small urban homes', 'Cities and environment', 'More city residents grow plants and vegetables on balconies or windowsills. Why is this popular? What benefits and limitations does it have?', 'Urban gardening can begin with a few containers even when a household has no private land.', 'Interest in food and a desire for nature help explain its popularity, although small scale growing cannot replace wider environmental measures.', 'Growing herbs gives a resident something fresh to use in cooking and a visible process to care for. Social media and community groups make techniques easier to discover, while the activity can provide a break from screen based routines. For people who rarely visit green spaces, a balcony garden offers an immediate connection to seasonal change within the home.', 'The benefits include enjoyment, small food savings and opportunities for children to observe growth. However, light, space and building safety limit what can be grown, and a few pots make little difference to the city’s overall food supply. Safe placement and sensible water use matter. Councils should continue protecting parks and larger community gardens rather than treat private containers as a substitute for accessible shared nature.', 'small gardens are popular because they combine practical interest with everyday contact with nature, and their genuine personal benefits should be recognised without exaggerating their capacity to solve urban environmental problems.'],
  ['public-free-wifi', 'Free wireless internet in public places', 'Technology and public services', 'Many towns provide free wireless internet in public spaces. Why do they do this? What precautions should users take?', 'Public internet access can make a town’s services easier to use, but convenience does not remove security risks.', 'Authorities seek inclusion and convenience, while users need to check connections and protect sensitive information.', 'A visitor can find transport information or a local map without purchasing additional mobile data. Residents with limited connectivity may also complete basic tasks, especially when access is available near libraries or service centres. Businesses can benefit from a more accessible area. However, a public network should complement affordable home access rather than assume that essential private tasks can always be completed comfortably in a square.', 'Users should confirm the official network name and avoid connections that imitate it. Sensitive accounts require secure websites, strong authentication and updated devices, while important transactions may be better completed on a trusted connection. Authorities should explain what data they collect and avoid requiring unnecessary personal details. A free service is less valuable if its costs are hidden in intrusive tracking or poorly protected information.', 'public wireless access can support inclusion and navigation, but responsible provision and cautious use are needed so that an easy connection does not become an invitation to expose personal data.'],
  ['job-personal-purpose', 'Choosing work for social purpose', 'Employment and values', 'Some young adults choose jobs that help society even when these jobs pay less. Why might they make this choice? Should employers rely on this motivation?', 'A career decision can reflect what a person values as well as the income the role provides.', 'Meaning and direct contribution explain the choice, but employers must not use commitment as a reason to offer unfair conditions.', 'A person may find satisfaction in seeing how their work improves another life, particularly after experience as a volunteer or recipient of support. Working for an environmental organisation or a community service can also align daily tasks with personal beliefs. If basic financial needs are met, that connection may reasonably matter more than a higher salary in an occupation the person finds unfulfilling.', 'However, motivation does not remove rent, care obligations or the risk of exhaustion. Organisations that depend on underpayment exclude people without family support and may lose skilled staff as responsibilities grow. Fair wages, manageable workloads and progression remain necessary. Employers can recognise purpose as a strength while budgeting honestly for the labour required, rather than imply that asking for reasonable pay shows insufficient commitment to the mission.', 'socially meaningful work can be a rational personal choice, but lasting contribution depends on fair employment rather than expecting workers to subsidise an organisation’s purpose through low pay or excessive hours.'],
  ['children-public-speaking', 'Children learning to speak to an audience', 'Education and communication', 'Schools increasingly ask children to give presentations to classmates. Why is this considered useful? How can teachers ensure that all pupils benefit?', 'Presenting an idea requires a child to organise thought and consider what listeners need to understand.', 'The activity develops communication, but useful practice must be supportive and adaptable rather than a test of natural confidence.', 'Preparing a short talk encourages pupils to select relevant information and explain connections in their own words. Questions from classmates can reveal unclear reasoning and create a genuine reason to improve it. These skills are useful beyond formal speeches, including discussions and interviews. However, confident delivery should not be mistaken for deeper understanding when the explanation itself is weak.', 'Teachers can begin with pairs or small groups before requiring a large audience. Clear criteria should value structure, evidence and improvement, not only volume or eye contact. Pupils with speech difficulties or severe anxiety may need alternative formats and gradual support. Feedback should identify one useful next step, while classroom rules prevent ridicule, making repeated practice safer than a single highly pressured performance.', 'presentations help pupils organise and communicate ideas, but broad participation depends on gradual practice, fair criteria and respectful feedback rather than rewarding only those who already enjoy public attention.'],
  ['wildlife-city', 'Wild animals living in cities', 'Environment and urban life', 'Wild animals are increasingly seen in some cities. Why does this happen? How should residents respond?', 'Urban areas can offer food and shelter to wildlife even while replacing parts of its original habitat.', 'Habitat change and easily available food explain the presence, and residents should respond with informed caution rather than automatic hostility.', 'Development can remove natural space, while gardens, bins and warm structures provide new opportunities. An animal that learns to find food near people may return regularly, especially when deliberate feeding reinforces the habit. Increased sightings can also reflect recovering populations, so the same observation does not always mean that conditions in the wider environment have improved or deteriorated in one simple way.', 'Residents should secure food waste, avoid approaching or feeding unfamiliar animals and obtain local advice about genuine risks. Cities can maintain habitat corridors that reduce conflict and give wildlife appropriate space. Intervention should be proportionate: a harmless visitor does not justify indiscriminate removal, while an injured or dangerous animal requires trained assistance. Education can replace sensational reactions with practical steps suited to the species involved.', 'animals use cities because both pressures and opportunities draw them there, and coexistence is more likely when residents manage food and space responsibly while leaving risky interventions to qualified people.'],
  ['public-service-feedback', 'Inviting feedback on public services', 'Society and government', 'Public services increasingly ask users to rate their experience. Why is feedback useful? What are the limitations of relying on ratings?', 'User feedback can reveal a problem that administrative statistics alone do not show.', 'It helps identify practical barriers, but ratings need interpretation and cannot replace professional standards or representative evidence.', 'A transport service may record that a bus arrived on time while failing to notice that announcements were inaudible or a stop was inaccessible. Users describe these everyday details and can point to recurring patterns. When services explain how comments led to changes, feedback also builds trust. The value lies in learning something specific, rather than merely displaying a high score as publicity.', 'People leaving ratings may not represent all users, and a very positive or negative event can dominate the response. A doctor providing necessary but unwelcome advice might receive a poor score without delivering poor care. Services should combine comments with inspections, outcome measures and outreach to people unable to respond online. Questions should distinguish staff conduct, access and results rather than reduce everything to one number.', 'feedback is valuable for understanding lived experience, but sound evaluation combines it with representative information and professional judgement instead of assuming that popularity and service quality are always the same.'],
  ['workplace-care-support', 'Supporting employees who care for relatives', 'Employment and family', 'Some employers provide special support for employees caring for relatives. Why might this be beneficial? What forms of support are most useful?', 'Caring responsibilities can affect work even when an employee is not a parent of a young child.', 'Support can retain experienced staff and reduce crisis absence, with flexibility and clear procedures offering the greatest practical value.', 'A worker arranging an elderly parent’s treatment may leave a job if every appointment creates conflict with a rigid schedule. Replacing that employee costs money and removes accumulated knowledge. Support also makes it easier to discuss problems early, allowing a team to plan cover rather than discover an absence at the last moment. The benefit therefore extends beyond a gesture of goodwill.', 'Useful measures include predictable flexibility, short term leave and access to clear information about entitlements. Managers should discuss arrangements confidentially and assess actual tasks rather than assume that flexibility means reduced commitment. Teams need fair workload planning so colleagues are not silently expected to absorb everything. Occasional remote work helps some carers, but it is not a complete substitute for time to provide necessary care.', 'employers benefit when experienced workers can manage responsibilities sustainably, and practical, transparent arrangements are more effective than sympathetic statements unsupported by leave, flexibility or adequate team planning.'],
  ['local-craft-revival', 'Renewed interest in handmade crafts', 'Culture and consumption', 'Some traditional crafts are attracting renewed interest among younger people. Why is this happening? How can communities support the interest?', 'Handmade work can appeal to people whose daily tasks otherwise produce few tangible results.', 'A desire for meaningful activity and distinctive products drives the revival, which needs affordable learning and viable opportunities for craftspeople.', 'Making pottery, weaving or working with wood offers visible progress and a break from digital routines. Buyers may also value the story and individuality of an object rather than identical mass produced goods. Online sharing makes techniques and makers easier to discover. Interest can therefore connect cultural curiosity with a practical desire to create, not simply nostalgia for a life nobody has experienced.', 'Communities can provide shared workshops, introductory classes and fair markets where makers receive a reasonable return. Experienced craftspeople should be paid for teaching rather than expected to preserve skills without income. Safe equipment and affordable workspace matter, especially in cities. Documentation helps, but continued practice requires people able to make a living or sustain the activity without prohibitive costs.', 'crafts attract interest through creativity and tangible connection, while their future depends on access to skills and fair economic support rather than displaying tradition as something valuable only in a museum.'],
  ['school-outdoor-lessons', 'Taking lessons beyond the classroom', 'Education and environment', 'Some schools conduct regular lessons outdoors. Why might this be useful? What difficulties must schools consider?', 'An outdoor setting can give pupils direct evidence to observe instead of relying entirely on a page or screen.', 'It is useful for carefully chosen learning aims, but safety, access and weather require planning.', 'A science class can compare soil or notice how plants respond to shade, while a geography lesson can examine drainage around the school. These observations create questions that feel concrete and encourage pupils to connect an explanation with something they have seen. Movement and a different setting may also help engagement, although outdoor teaching should not be assumed to improve every subject automatically.', 'Weather and noise can interrupt a lesson, and some pupils may need accessible paths, appropriate clothing or additional support. Teachers require a clear task and manageable boundaries, not merely permission to take a class outside. Nearby school grounds can offer frequent, low cost opportunities without the complexity of a distant trip. An indoor alternative keeps learning reliable when conditions are unsuitable.', 'outdoor lessons are valuable when the environment provides evidence relevant to the task, and inclusive planning ensures that the experience supports learning instead of introducing avoidable discomfort or exclusion.'],
  ['digital-memories', 'Keeping personal memories online', 'Technology and family', 'People increasingly store photographs and personal memories on online services. Why do they choose this method? How can they protect these memories?', 'Online storage makes a large personal collection available without keeping every file on one device.', 'Convenience and sharing explain the choice, but preservation requires independent copies and attention to access and privacy.', 'A phone can upload images automatically, reducing the chance that a lost device removes every recent photograph. Relatives living apart can also share an album without sending separate files. Search and date sorting make a large collection easier to explore. These features are attractive, but they can create the impression that a commercial service will always remain available and unchanged.', 'Users should keep another copy in a separate place and check that important files can be exported in a common format. Strong authentication and recovery details protect access, while thoughtful sharing settings reduce unwanted exposure of family information. Accounts should also be reviewed when a provider changes its terms. A memory stored online remains vulnerable to deletion, technical failure or loss of login credentials.', 'online services simplify access and sharing, but reliable preservation depends on backup, usable formats and secure account management rather than assuming that automatic upload guarantees permanent custody.'],
  ['small-business-apprentice', 'Small firms teaching practical skills', 'Employment and education', 'Some small businesses train young people directly instead of hiring only experienced staff. Why might this be valuable? What support do these businesses need?', 'A small firm can pass on skills through daily work, but training competes with immediate production demands.', 'The approach expands entry opportunities and protects specialist knowledge, provided that firms receive help to teach safely and consistently.', 'Young people gain a route into an occupation without already possessing experience they could obtain only by being hired. An experienced worker can explain judgement developed through practice, such as identifying a fault or dealing with a customer. The firm also builds a workforce familiar with its methods. This is especially important where a specialist owner may otherwise retire without passing the skill to anyone.', 'Small firms need straightforward guidance on training standards, safety and fair pay. Shared courses can teach foundations that an individual workshop cannot cover, while modest funding can compensate for supervised learning time. Support should check that trainees receive meaningful instruction rather than perform routine tasks indefinitely. Cooperation among firms can also provide a wider range of experience and reduce dependence on one trainer.', 'direct training benefits young workers and preserves practical expertise, but its quality depends on supervision, wider learning and fair conditions, supported in ways small employers can realistically manage.'],
  ['time-notifications', 'Reducing phone notifications', 'Technology and wellbeing', 'More people are turning off notifications on their phones. Why do they do this? How can they remain reachable without being constantly interrupted?', 'A phone can demand attention for many events that do not require an immediate response.', 'People seek greater concentration and control, and selective communication rules can preserve important contact.', 'Repeated alerts fragment work, conversations and rest, even when each message takes only a moment to read. Some people also feel pressure to respond because others can see that a message was delivered. Turning off nonessential alerts restores a choice about when to check information. The aim is often to use the device more deliberately rather than reject communication altogether.', 'Users can allow calls from a few necessary contacts and agree an urgent channel for genuine emergencies. Checking ordinary messages at predictable intervals helps colleagues and family understand when a reply is likely. Work teams should also state which tasks need immediate attention, avoiding the assumption that every group update does. The arrangement needs flexibility for care or on call duties, but permanent interruption should not be the default.', 'fewer notifications can improve attention and reduce response pressure, while clear exceptions and shared expectations keep people reachable for important matters without giving every application equal claim on their time.'],
];

const essayDetails: Record<string, string> = {
  'school-breakfast': 'There is also a distinction between making food available and ensuring that children will eat it. An unfamiliar menu served in a rushed corridor may attract little interest, even when the meal is nutritious. Pupils could help choose from suitable options, and schools could allow enough time to sit down calmly. Staff should monitor participation and waste without labelling individual children by income. This would make adjustments possible and show whether the programme is actually reaching those who need it, instead of judging success only by the number of breakfasts purchased.',
  'repair-label': 'The right would be incomplete if a company published instructions but made the required part unaffordable. A household deciding whether to repair a kettle needs to compare a realistic total price, including the technician’s time, with replacement. Rules should therefore require reasonable access to common components for an appropriate period after sale. They should not force a small manufacturer to hold every item forever, but published availability commitments would let buyers choose products with a credible future. This links the information requirement to an actual opportunity to keep equipment working.',
  'car-free-school': 'Implementation should involve the people whose journeys overlap at the school gate. A nearby shop may need a delivery, and an older resident may depend on a visiting carer. These needs can usually be accommodated through specific time windows or controlled access without reopening the street to ordinary through traffic. Schools should explain the arrangements before a trial begins and collect observations at surrounding crossings. A quieter entrance is not a complete success if children then face a queue of turning vehicles at the next corner on their walking route.',
  'public-library-evening': 'Demand should be assessed among potential users as well as current visitors. A library that closes early will naturally record few working adults in its attendance figures, which cannot prove that evening opening is unnecessary. A trial on selected days, advertised through workplaces and colleges, would provide better evidence. Staffing arrangements also matter: extending public hours should not depend on the same employees repeatedly working excessive shifts. Shared cover and predictable rotas can make later access sustainable while allowing the council to decide whether the additional service merits continued funding.',
  'food-marketing-child': 'Parents retain an important role, but responsibility cannot reasonably be placed on them alone. A child may encounter promotion through several platforms that an adult cannot supervise continuously. Restrictions reduce that background pressure and make household guidance easier to follow. Enforcement should focus on the companies designing and paying for campaigns, rather than punish children for wanting an advertised snack. Independent review of campaign content would also be preferable to allowing each advertiser to declare that its own characters, challenges or prizes were intended mainly for adults.',
  'work-email-hours': 'The rule should distinguish sending a message from requiring an answer. A manager working at a different time may reasonably draft instructions in the evening, provided the system clearly indicates that staff should respond during their next shift. Scheduled delivery can reduce ambiguity. Performance reviews must also reflect the policy: workers will not truly disconnect if promotions quietly favour those who reply at midnight. The legal protection therefore needs ordinary management practice behind it, including workload planning and a safe way to raise concerns without being regarded as uncooperative.',
  'river-personhood': 'Public access is another reason to resist poorly controlled development. A riverbank lined entirely with private restaurants may improve the view for paying customers while cutting off a route used by everyone else. Planning conditions should preserve continuous paths and areas where people can rest without purchasing anything. Ecological protection and social access need not prevent attractive buildings, but they should be secured before permission is granted. Once structures occupy the available land, asking the council to recover space later can involve lengthy disputes and expensive compensation.',
  'student-councils-budget': 'Learning requires pupils to see what happens after the vote, not merely take part in a campaign. If they choose new sports equipment, they should help establish how it will be stored and shared, then review whether it has been used as expected. An unsuccessful purchase can become a useful lesson if the process is discussed honestly. Staff should not immediately take the budget back whenever a decision disappoints, because that would suggest that student authority exists only when pupils make the choice adults already preferred.',
  'holiday-flight-tax': 'The measure would work best if travellers knew the rising charge before choosing their holiday pattern. Clear annual allowances and accessible records could prevent unexpected bills and reduce the opportunity for airlines to conceal the tax inside complicated pricing. Governments would also need to cooperate, since a traveller might otherwise depart from a neighbouring country to avoid the charge. Such arrangements are administratively demanding, but they are not a reason to ignore repeated high impact travel. They are a reason to begin with transparent, manageable rules and review evasion.',
  'museum-return': 'Return can also change who has authority to interpret an object. A museum label may describe artistic technique while giving little attention to the ceremony or community relationship from which the item came. Collaboration before a transfer can preserve research and create exhibitions explaining the object’s journey. Copies or agreed loans may maintain access for international audiences, but these should follow the originating community’s consent. They must not be used as a condition that makes return effectively impossible, especially when ownership and the original absence of permission are clear.',
  'rental-pets': 'A workable process needs a decision deadline and written reasons. Otherwise, a nominal right to apply can leave tenants waiting indefinitely or receiving an unexplained refusal. Landlords should be able to request evidence about the proposed animal and the property, but not impose arbitrary requirements unrelated to risk. Tenants, in turn, must respond when a genuine nuisance occurs. This creates a continuing responsibility rather than permission without consequences, allowing a quiet, well cared for animal to be treated differently from a documented pattern of damage or disturbance.',
  'sports-equal-prize': 'Predictability matters for the organiser as well as the athletes. A public grant should state the equality condition before a competition’s budget is set, rather than demand a sudden change after contracts have been signed. Smaller events may need transitional support to meet the requirement without cancelling a category. Athletes should also be consulted about how resources are distributed, since an equal cheque at the end cannot compensate for unsafe accommodation or inadequate medical provision. Fair recognition is strongest when it forms part of credible, comparable conditions throughout the event.',
  'local-food-schools': 'Procurement rules can unintentionally exclude the farmers the scheme is meant to help. A small grower may produce good food but be unable to supply every school in a district or complete a complex tender alone. Schools could divide contracts into manageable lots or work with a cooperative that combines harvests and transport. Quality and safety standards should remain, while paperwork should be proportionate. This would support genuine local participation rather than give the entire contract to one large distributor that merely markets its service as local.',
  'voting-sixteen': 'The change should be accompanied by opportunities to question candidates and compare proposals, not just a lesson on the voting procedure. Young voters may care about an issue but need help understanding which institution has authority over it. Schools can provide balanced materials and invite several perspectives while protecting pupils from pressure to reveal their choice. Adults should not demand that teenagers pass a political knowledge test that older voters never face. The aim is to support informed participation within the same basic democratic rights, not create a second class electorate.',
  'city-night-buses': 'An overnight network should be understandable to someone who uses it only occasionally. A worker covering an unexpected late shift needs clear stop information and a reliable connection, not a timetable that changes unpredictably by day. Coordination with hospitals and other major employers could improve both route planning and awareness. Drivers also need reasonable breaks and support when handling safety concerns. Subsidy should therefore fund a dependable service with appropriate working conditions, rather than merely keep a vehicle moving for longer while ignoring the people operating and using it.',
  'university-recorded-lectures': 'Access should extend beyond uploading a video file. Accurate captions, searchable sections and a reasonable viewing format make the material useful to students with different needs. A lecturer may also need technical support to correct an error or remove confidential discussion before release. Universities should establish who can view and redistribute recordings, protecting both students and teaching staff. These practical requirements involve some cost, but they are part of delivering a meaningful learning resource. A recording that cannot be heard, navigated or trusted offers only the appearance of accessibility.',
  'fast-fashion-responsibility': 'The financial contribution should reflect how difficult a garment is to keep in use. A coat with replaceable fastenings and accessible repair instructions should not face the same charge as a fragile item designed around frequent replacement. Such distinctions give a producer a reason to improve construction rather than simply pass a uniform fee to customers. Rules must be independently checked, because exaggerated durability claims could otherwise attract a discount without changing the product. The purpose is to prevent waste upstream, not merely fund a larger disposal operation after the clothes are unwanted.',
  'remote-work-rural': 'A relocation scheme also needs a long enough horizon to judge its effect. A brief increase in population may look successful before newcomers discover that the nearest clinic is overstretched or that their employer has restored office attendance. Grants could therefore be paid in stages, with clear residence conditions and support for local integration. Existing residents should have a say in choosing investments, particularly where housing or services are already under pressure. This would make the programme a community development tool rather than a competition to attract a handful of well paid individuals.',
  'public-art-maintenance': 'Maintenance decisions should not preserve every object automatically regardless of its condition or relevance. Some works may be expensive to repair without retaining meaningful artistic value, and a community may reasonably choose relocation or careful removal. That decision requires documentation and consultation, including consideration of the artist’s intentions. An inventory with expected care costs would make the choices visible before deterioration becomes an emergency. It would also help councils compare a new commission with other cultural uses of the same money, rather than treating maintenance as an unpredictable expense that can always wait.',
  'packaging-delivery': 'A shared return system could make the charge more acceptable than asking every customer to carry a personal container. Someone buying lunch near work might return a borrowed box at a participating shop on the following day. The deposit must be easy to recover, including without a smartphone, and the network needs enough return points to fit ordinary journeys. Restaurants should publish the container charge before checkout. These details determine whether customers have a genuine choice or face a compulsory cost attached to an alternative they cannot conveniently use.',
  'homework-weekend': 'The content of a task is as important as its timing. Asking pupils to photograph an expensive family outing would favour those with resources, whereas observing a plant or revising a short passage can be completed more widely. Teachers should estimate the combined load across subjects and invite honest feedback about how long tasks take. If a brief assignment regularly occupies several hours, its design needs revision. This approach respects the argument for practice without accepting that every additional minute at a desk represents a useful educational gain.',
  'urban-trees-parking': 'The comparison should also include people who are not current drivers. Children, carers pushing a pram and residents without a car use the street but receive no direct benefit from a parking space. Their needs can disappear when consultation counts only objections from vehicle owners. Equally, a badly chosen tree may damage a narrow pavement or obstruct a crossing. Appropriate species and sufficient soil space are essential. The strongest plan would therefore assess access for all users and the future care of the canopy, rather than simply count trees planted or bays removed.',
  'exam-open-book': 'Question design can prevent the open book option from becoming a search exercise. Students might be asked to compare two plausible solutions and justify which fits an unfamiliar case, making copied definitions insufficient. Conversely, a closed test should explain which core knowledge students are expected to retain, avoiding surprises based on trivial details. A course using both formats can provide practice in each and make the assessment purpose clear. This preserves the legitimate benefits claimed by both groups while reducing the chance that success depends mainly on guessing the examiner’s preferred method.',
  'hospital-visitors': 'Patients should also have a say in who visits and for how long. Flexible access must not create pressure to receive relatives when someone needs quiet or does not want a particular person present. Staff can record consent and discuss arrangements as the patient’s condition changes. In a shared ward, a compromise may involve a designated conversation space rather than long gatherings beside the bed. This makes flexibility responsive to the person receiving care, not merely convenient for visitors, and protects the privacy of patients whose circumstances are less visible.',
  'tourism-entry-fee': 'How the revenue is controlled affects whether a fee is acceptable. If ticket income enters a general budget while the trail remains damaged, visitors and residents may doubt the conservation justification. Managers should publish understandable accounts and describe the work funded by admission. Charges should also be reviewed when demand changes, since a high price does not necessarily protect a site if operators continue admitting unlimited numbers. A capacity limit and an accessible pricing policy can achieve different purposes, and both should be considered rather than expecting payment alone to solve crowding.',
  'work-four-day': 'An employer should consult staff about the arrangement instead of assuming everybody wants the same free day. A parent may prefer shorter daily hours, while another worker benefits from a full additional day away. The organisation can identify where coverage is essential and test different patterns with agreed workload measures. Success should include whether staff are actually working fewer hours, not merely whether office doors close earlier. Hidden evening work would undermine the promised recovery and could leave the shortest official week associated with the least honest record of employee effort.',
  'language-global-local': 'Teachers and employers can reduce the perceived conflict by explaining that language choice depends on purpose. A student may use an international language for a research paper and a local language for a community interview, developing different skills through both. Resources are needed for the smaller language, including modern vocabulary and attractive reading material. Otherwise, calling the policy bilingual may conceal a system in which only the dominant language supports serious study. Equal practical respect matters more than ceremonial praise for linguistic diversity during occasional cultural events.',
  'technology-elderly': 'Public bodies should test a new service with people who have different levels of digital confidence before removing existing access routes. A form that seems clear to its designers may require terminology or repeated authentication that confuses an occasional user. Staff assistance should be confidential, especially when personal benefits or health information are involved. Relatives can help voluntarily, but citizens should not be required to disclose private information to family members in order to obtain a public service. Independence includes the ability to choose a suitable way of receiving help.',
  'school-uniform-choice': 'Enforcement often determines whether a clothing policy feels fair. Punishing a pupil for a missing branded item may remove them from a lesson even when the family cannot replace it immediately. Schools should distinguish a genuine safety problem from a minor appearance difference and offer practical assistance where needed. Pupils can contribute to reviewing the code, identifying fabrics or styles that are uncomfortable. A clear, modest policy with proportionate responses would preserve order more convincingly than strict rules that consume teaching time and embarrass children over their household circumstances.',
  'zoos-conservation': 'A conservation claim should be specific enough to check. Funding habitat protection, contributing to a coordinated breeding programme or publishing useful research provides more evidence than simply displaying an endangered animal. Institutions should also explain when release is not feasible and why captivity remains appropriate. Visitors can then judge the role honestly instead of assuming every enclosure leads eventually to reintroduction. Where the conservation contribution is weak and welfare needs cannot be met, an attractive educational sign does not justify keeping the animal for entertainment or ticket income.',
  'city-growth-outward': 'Housing quality must be assessed at the neighbourhood level as well as inside each building. A dense development without schools, shade or public space can leave residents dependent on distant facilities despite a central address. Equally, a new outer district with a reliable rail link may work better than its distance suggests. Planning should compare full journeys, service capacity and future maintenance. This avoids reducing the debate to towers versus gardens when the more useful question is how a household can live comfortably without imposing excessive transport and infrastructure demands.',
  'news-local-global': 'Newsrooms should connect the two scales instead of keeping them in completely separate sections. An international change in food supply can be explained through interviews with local retailers and households, while a local flood can be linked to wider research on climate and land use. Such reporting helps readers understand why a distant event matters without replacing evidence with speculation. It also gives local journalists a distinct contribution to make. A balanced service need not reproduce every global headline if it explains selected events well and continues investigating nearby institutions.',
  'university-industry': 'Students need to understand the conditions attached to a partnership before they join a project. A placement can provide valuable experience, but restrictions on discussing the work may limit what they can demonstrate when applying for jobs or writing a thesis. Universities should define acceptable confidentiality and retain the ability to assess learning independently. Public disclosure of funding also lets readers interpret a study’s interests without assuming that sponsored work is automatically invalid. The aim is accountable cooperation, recognising the partner’s legitimate needs without allowing them to override the educational purpose.',
  'water-pricing': 'The distinction between affordability and price should guide the policy. A household can receive assistance with essential bills while the service still charges for use and funds maintenance. Authorities must also reduce leakage, otherwise users are asked to conserve while substantial water is lost before reaching their homes. Transparent reporting would show whether revenue improves reliability. A well managed system can protect basic access and discourage waste simultaneously, whereas either unlimited free provision or an unaffordable uniform tariff ignores an important part of the problem.',
  'science-space-ocean': 'Research programmes should be compared on their actual questions rather than their labels. A satellite studying sea temperatures can directly support ocean management, so the boundary between the fields is not absolute. Agencies can share data and invite independent assessment of expected benefits, uncertainties and costs. Some fundamental projects will still lack an immediate application, and a sensible portfolio should allow them. The priority I favour concerns additional spending on urgent marine problems, not a claim that every ocean project is more useful than every mission beyond Earth.',
  'sports-specialise': 'A child’s own experience should be central to the decision. Enjoyment, recovery and willingness to continue are better guides than an adult’s belief that early success guarantees a professional career. Coaches can explain pathways without presenting one irreversible choice. Time for education and friendships must remain protected, especially when training requires long travel. If a young athlete later specialises, broader skills and a healthier relationship with activity may support that commitment. Leaving one competitive programme should also remain compatible with continuing sport for pleasure rather than be treated as failure.',
  'family-meals': 'The routine should not place all preparation work on one person. A shared dinner can appear to unite the family while exhausting the adult expected to cook and clean after a working day. Simple meals, rotating tasks and contributions suited to children’s ages make the occasion more genuinely shared. Phones can be set aside for a short period, but conversation should not feel like an interrogation. A flexible gathering becomes valuable through attention and mutual effort, whereas a perfectly timed meal with resentment or silence may offer little of the claimed emotional benefit.',
  'heritage-modern-use': 'The financial model also matters. If adaptation relies on expensive private events, the building may survive physically while becoming less accessible to the people whose history it represents. Planning agreements can retain public visits, visible interpretation and community use alongside commercial activity. Conversely, insisting on a use that cannot pay ordinary upkeep may return the site to neglect. A realistic assessment should combine conservation significance, public value and running costs. This gives the debate a practical basis instead of assuming that either commercial reuse or exact preservation automatically protects heritage.',
  'health-prevention-treatment': 'Prevention programmes need the same scrutiny as treatment spending. A campaign may reach people already following healthy routines while missing those whose housing or work makes change difficult. Measures such as safer streets or affordable nutritious food can address these barriers more directly than repeated advice. Evaluation should also allow time for benefits to emerge, without using distant promises to avoid checking progress. At the same time, hospitals must remain able to respond to illness that prevention cannot remove. The two priorities support one another when referrals and resources are planned coherently.',
  'citizen-juries': 'Accountability should remain visible after consultation. If officials reject a panel’s recommendation, they should explain whether cost, legal duties or conflicting evidence led to that decision. Otherwise, participation can become a performance that leaves citizens more cynical. Experts should likewise describe uncertainty and disagreements within their field rather than present a preferred option as technically inevitable. An informed panel can weigh values among feasible alternatives, while elected representatives remain answerable for the choice. This division of roles respects knowledge without treating a specialist qualification as permission to decide every public priority.',
  'adult-language-classes': 'The class can also offer a setting in which age is not treated as a reason to stop developing. A learner may enjoy finally holding a short conversation with a grandchild who lives abroad, even if fluent speech remains a distant goal. Teachers should recognise such progress instead of measuring everybody against an examination timetable. Accessible fees, transport and learning materials would widen participation beyond comfortable retirees. The benefit is strongest when the course helps people pursue their own purposes and form relationships, rather than presenting learning as another obligation they must fulfil.',
  'park-paid-activities': 'Restrictions should distinguish a small group using a corner briefly from an organiser repeatedly reserving a large area. A blanket ban could remove an affordable exercise option that many residents value. A graduated permit system can respond to actual impact, including equipment, crowding and the time of day. Some free community sessions might receive support, but they still need to respect other users. The park should retain its ordinary functions throughout the week, not offer public access only in the gaps left after commercial bookings have chosen the most convenient hours.',
  'financial-school-lessons': 'Financial teaching should also explain uncertainty. A budget based on exactly the same income every month may not fit a household with seasonal work, and a purchase that looks affordable can become difficult after an unexpected bill. Pupils can practise adjusting a plan rather than produce one neat answer. Schools should use neutral examples and disclose any commercial involvement in materials. Otherwise, a lesson intended to develop independence could become an opportunity for a lender to introduce its brand as the natural choice before students know how to compare alternatives.',
  'public-screens-adverts': 'The appearance of public space has a cumulative effect that individual applications may overlook. One modest screen might seem acceptable, yet several competing displays can make the same junction visually chaotic. Planning should consider the whole area and protect places where people can spend time without continuous promotion. Residents should also have a way to report brightness problems after installation. Any emergency information function can be provided through proportionate public displays, rather than granting an advertiser extensive exposure in return for a rarely used promise to carry important messages.',
  'food-worldwide': 'Availability does not mean that every household can afford the new variety. A supermarket may devote more shelf space to fashionable imported products while offering fewer inexpensive staples. Retailers should respond to actual community needs, including ingredients used by local migrant families rather than only items promoted as exotic. Cooking guidance can help unfamiliar buyers use a product without wasting it. This makes the expansion more inclusive and useful, turning global supply into everyday cultural exchange instead of a display of luxury choices disconnected from ordinary food budgets.',
  'retirement-volunteering': 'Continuity matters because volunteers may have health needs, travel plans or family duties of their own. An organisation should arrange cover rather than depend entirely on one retired person for an essential service. Clear descriptions of the role also help volunteers decide whether they can make the commitment. A former accountant may welcome occasional financial advice but not want to reproduce the full responsibilities of employment. Respecting those boundaries allows contribution to remain a chosen, rewarding activity and reduces the chance that enthusiasm turns into fatigue or resentment.',
  'career-switches': 'Successful transition also requires a credible account of what the person already knows. A hospitality manager moving into logistics may bring experience in scheduling, suppliers and resolving urgent problems, even without a matching job title. Career advice should help identify these connections while being honest about gaps. Employers can use practical assessments and structured training rather than require every applicant to have followed one traditional route. This reduces unnecessary repetition of study and gives career changers a way to demonstrate value without pretending that all prior experience transfers automatically.',
  'heritage-experience-travel': 'The visit can reveal whose experience is missing from a familiar account. A palace may be described through its rulers, while service rooms show the labour that sustained their lives. Interpretation that includes workers, residents and later uses can challenge the visitor’s initial picture. Access should remain respectful, particularly at sites associated with suffering or ongoing religious practice. Taking time to ask questions and read different sources turns travel into a starting point for learning, rather than a claim that a dramatic atmosphere provides direct knowledge of what people once felt.',
  'balcony-gardens': 'The household benefits depend on choosing plants suited to the space. A resident with a shaded window may succeed with a modest selection but become discouraged by copying a sunny rooftop shown online. Advice from local groups can prevent expensive purchases and unsuitable containers. Shared tools or seedlings reduce the cost of trying the activity. Building managers should explain safety limits clearly, especially where heavy pots or dripping water affect neighbours. Gardening then remains an accessible source of pleasure rather than an attempt to reproduce an idealised display in an impractical setting.',
  'public-free-wifi': 'Security is also the provider’s responsibility. Users cannot assess the network’s configuration while standing at a bus stop, so authorities should maintain the system, offer a recognisable connection and explain its limitations. A long registration process may discourage access while collecting more information than needed. The public benefit is stronger when basic connectivity is straightforward and privacy is respected. Guidance should be available in plain language at the location, allowing an occasional visitor to make an informed choice without first needing internet access to find the safety instructions.',
  'job-personal-purpose': 'Meaning can also change over time. A worker may begin with enough savings to accept lower pay, then become responsible for a child or an elderly relative. An organisation that offers no progression risks losing committed employees precisely when their experience becomes most valuable. Funding proposals should therefore include realistic staffing costs instead of advertising a mission on the assumption that devotion will fill the gap. Fair conditions allow a more diverse group to contribute, including people who share the purpose but do not have another household income to support them.',
  'children-public-speaking': 'Listening deserves attention alongside delivery. Pupils can learn to ask a relevant question, identify the strongest evidence and respond respectfully when they disagree. These roles let a quieter child contribute while gradually developing confidence to present. Recording a short explanation can provide another practice route, with appropriate consent and privacy. Teachers should review improvement over time instead of making one nervous performance decisive. The educational purpose is to make ideas understandable and support dialogue, not train every child to imitate the same polished style of a professional speaker.',
  'wildlife-city': 'Responsibility extends to the design and management of neighbourhoods. Open food waste attracts animals, while continuous fencing can block routes they previously used. Coordinated advice for households and businesses prevents one property’s precautions from being undermined by waste left next door. Residents should be told which sightings need reporting and which are ordinary. This reduces unnecessary fear and allows specialists to focus on real problems. Accepting wildlife nearby does not mean ignoring danger, but it does require a response based on behaviour and species rather than surprise alone.',
  'public-service-feedback': 'A useful feedback process must lead to a visible response. If users repeatedly report the same inaccessible entrance and hear nothing, collecting another survey can increase frustration. Services should explain which changes are possible, when they will happen and why some requests cannot be met. They can also invite detailed accounts from people who stopped using the service, since satisfied regular users are not the whole population. This turns feedback into a way of discovering and resolving barriers, rather than a routine exercise designed mainly to produce a favourable public score.',
  'workplace-care-support': 'Employees should not have to reveal every detail of a relative’s condition to obtain reasonable support. A clear application route and confidential records can establish what adjustment is needed without unnecessary intrusion. Arrangements should be reviewed as circumstances change, because some responsibilities are temporary while others continue for years. Managers need training to apply the policy consistently and avoid treating one worker more favourably simply because their family situation is familiar. This makes support dependable and helps employees plan, which in turn allows the organisation to manage staffing more honestly.',
  'local-craft-revival': 'Support should allow tradition to develop rather than require makers to reproduce only an approved historical style. A young craftsperson may use an inherited technique to create an object suited to contemporary homes. That adaptation can keep the skill relevant and financially viable. Communities should explain the origins of the method while leaving room for creativity and crediting the people who teach it. Fair access to markets is equally important: a festival celebrating local craft has limited value if stall charges are too high for the local makers it claims to support.',
  'school-outdoor-lessons': 'Teachers also need to connect observations back to the subject. Collecting leaves can be enjoyable without teaching much unless pupils compare features, record findings and discuss what those findings suggest. A short outdoor task followed by careful classroom analysis may be more valuable than a long excursion with an unclear aim. Repeated use of a familiar site allows children to notice change over time. This encourages disciplined observation and helps them understand that learning outdoors is not simply a break from lessons, although enjoyment can support their willingness to participate.',
  'digital-memories': 'Preservation includes context as well as files. A photograph may survive perfectly but lose meaning when nobody remembers the people or occasion. Adding names, dates and brief explanations creates a more useful archive for future relatives. Families should also discuss who can access important collections if the account holder becomes unavailable, without casually sharing passwords. Selecting some material for a printed album offers another route to enjoying it. These steps prevent storage from becoming a growing pile that is technically secure but rarely seen or understood by the people who value it.',
  'small-business-apprentice': 'Training support should remain simple enough that a small employer can use it. A lengthy application for a modest allowance may consume the time intended for supervision. Shared advisers can help firms design a plan, record progress and identify gaps in experience. Trainees also need a person outside the immediate workplace whom they can contact about concerns. This safeguards the learning relationship without assuming every small business is either an excellent teacher or an exploitative employer. Practical oversight can strengthen trust and help genuine training continue as normal business demands change.',
  'time-notifications': 'Expectations must be negotiated with the people who send the messages. Turning off alerts may bring little relief if a supervisor still expects an immediate reply and interprets silence as neglect. Teams can state ordinary response times and reserve a separate channel for genuine urgency. Families may need different exceptions, especially where someone depends on assistance. Reviewing these arrangements keeps them suitable as responsibilities change. The aim is not to make contact impossible, but to ensure that attention is allocated according to actual need rather than whichever application produces the next sound.',
  'shared-laundry': 'The arrangement also changes how costs are distributed. Residents need to know whether each wash is charged separately or whether maintenance is included in rent. A heavy user should not quietly transfer every extra cost to a neighbour who washes little, but complicated payment equipment can make an ordinary task frustrating. Transparent charges and an accessible way to pay would protect trust. The building should also provide somewhere clean to fold clothes, because a machine alone does not reproduce all the functions a household previously performed comfortably inside its own flat.',
  'self-service-checkout': 'Loss of personal interaction is another cost that a transaction speed measure can miss. A regular shopper may need clarification about an offer or help carrying purchases, which a scanning station cannot provide. Staff should remain visible and approachable rather than be assigned only to resolving machine errors. Automation might release time for such assistance, but only if the employer actually retains enough workers. If the saving is achieved mainly by removing people, the customer receives a faster process in ideal conditions but a less supportive store when anything goes wrong.',
  'subscription-books': 'Authors and publishers are affected by the way subscription revenue is allocated. A reader may enjoy unlimited access while the person producing a specialist book receives little payment if the platform favours frequently opened titles. Transparent terms and fair distribution help preserve the variety subscribers expect. Libraries offer another form of shared access without the same household fee, although availability may be limited. Readers should therefore compare several routes instead of assuming that a commercial subscription is the inevitable replacement for buying books or using a public collection.',
  'city-congestion-charge': 'The use of revenue can determine whether the charge gains lasting acceptance. Drivers who pay but see no improvement may view it as a general tax rather than a transport measure. Published accounts should connect income to bus frequency, accessible stations or safer streets. Authorities also need to monitor journey times and pollution outside the charging boundary. A reduction in central traffic is valuable, but it should not be reported as complete success if vehicles simply take longer routes through residential areas whose residents have little influence over the original decision.',
  'apprenticeship-salary': 'Progression after the initial programme is crucial. A good apprenticeship should allow a learner to move between employers or continue to higher study if their interests change. Without those routes, an early practical choice can become an unnecessary limit on future opportunity. Schools should explain that university and apprenticeship paths are not always permanently separate. Employers can publish what previous trainees went on to do, while prospective learners should examine the recognised qualification and supervision offered. This makes the immediate wage one part of the decision rather than the only visible benefit.',
  'home-medical-monitoring': 'The workload generated by remote measurements must be planned. If a clinic receives hundreds of readings without enough staff to review them, the system creates an expectation it cannot fulfil. Patients should know which results trigger contact and how quickly a response can normally be expected. Routine trends may be reviewed at a scheduled appointment, while urgent symptoms still require a different route. These boundaries protect both patients and clinicians from the assumption that continuous data means continuous personal supervision, which could otherwise make the technology falsely reassuring.',
  'community-fridge': 'Respectful use is important to the project’s social benefit. A public list of who takes food would discourage people concerned about embarrassment, while the absence of any rules could allow a small group to remove everything. Simple guidance on taking reasonable amounts can preserve openness without intrusive checks. The fridge should be located where people can reach it safely and contribute without difficulty. Clear contact details allow faults to be reported promptly, making the service dependable enough to use while retaining its character as neighbourly sharing rather than a formal welfare test.',
  'tourism-home-rent': 'Guests also need to understand that a home is not identical to a hotel. Quiet hours, shared facilities and check in arrangements should be explained before booking, preventing disputes that could affect neighbours. Hosts should not promise a level of privacy or equipment they cannot provide. Local authorities can offer standard safety guidance and a manageable registration process for genuine occasional hosts. This would preserve a useful source of income while making responsibilities clear, instead of forcing all small hosts into a system designed either for large hotels or completely unregulated informal stays.',
  'school-digital-textbook': 'Ownership and software support introduce another long term expense. A school may buy devices cheaply, then discover that essential programmes require recurring payments or no longer support older hardware. Teachers need stable access to materials and a way to move them if a provider changes terms. Printed resources do not solve every problem, but they reduce dependence on one platform. A mixed approach can also let pupils choose paper for extended reading while using digital demonstrations for concepts that benefit from movement, rather than treat the device purchase as a complete teaching strategy.',
  'workplace-open-office': 'Workers should have some control over when they are available for interruption. A clear signal for focused work and agreed spaces for calls can make shared seating more tolerable. Managers must respect those arrangements; asking staff to use a quiet room while praising constant visibility sends a conflicting message. The design should also account for different sensory needs instead of assuming everyone responds similarly to noise. Consultation and a trial layout can reveal these differences before an expensive refurbishment fixes the office in a form that employees struggle to use.',
  'cashless-market': 'Privacy and financial access deserve attention as well. A customer buying an ordinary snack may not want every small purchase linked to a digital account, and a teenager may have cash but no suitable payment service. Traders should not be required to choose between serving these customers and receiving electronic payments from others. Clear arrangements for refunds also matter when a transaction fails or an item is returned. Offering both methods distributes convenience more fairly and avoids treating access to a bank account as a condition for participating in a local market.',
  'online-skill-certificates': 'The learning is more useful when a worker has an opportunity to apply it soon afterward. A course on data presentation, for instance, gains meaning through preparing a real report and receiving feedback from a colleague. Employers can connect courses to specific development plans rather than reward the number of certificates collected. Providers should explain prerequisites honestly, because a short advanced module may frustrate someone without the foundations it assumes. This makes the system a flexible way to build capability rather than a market in attractive badges that promise more than the instruction can deliver.',
  'vertical-farming': 'Resilience has to be assessed across the whole production system. An indoor crop is protected from a rainstorm but may depend on continuous electricity and replacement equipment. A power failure can therefore create a risk quite different from outdoor weather damage. Operators need backup arrangements and transparent accounts of resource use. The most convincing projects match the technology to a clear local need, such as supplying delicate leaves near consumers, rather than rely on dramatic claims that every food can be grown more sustainably inside a building regardless of climate or energy supply.',
  'language-auto-translation': 'The app can also support learning rather than replace it. A traveller might check a menu word, hear its pronunciation and then use it in a conversation, gradually building a small vocabulary. This approach recognises the tool’s convenience without handing it every exchange. Sensitive situations require more care: an uncertain medical instruction should be clarified with a qualified interpreter when possible. A fluent looking translation is not proof of accuracy, and users should remain willing to admit uncertainty instead of insisting that the screen has conveyed exactly what they intended.',
  'deposit-cups': 'Participation should not require customers to create an account for every café group. A straightforward deposit and refund can work without collecting personal information, making the system accessible to occasional visitors. Cafés also need enough cups in circulation and a clear responsibility for damaged items. If the scheme repeatedly runs out, customers return to disposables and staff lose confidence in explaining it. Reliable operations therefore support the environmental benefit. The value comes from many completed cycles of use, not from a launch campaign in which a reusable design is photographed and rarely returned.',
  'shared-workspaces': 'Professional boundaries still need attention in an informal environment. A freelancer discussing a client’s confidential information may require a private room, and casual conversation should not imply permission to view another person’s work. Shared offices can explain these expectations clearly. A trial day is useful before a long commitment, allowing the worker to assess actual noise, facilities and travel time. What feels inspiring during an organised tour may be unsuitable for daily concentration, so the decision should be based on the ordinary working atmosphere rather than the provider’s selected presentation.',
  'school-community-garden': 'A shared garden should retain an educational purpose without making residents feel like unpaid caretakers of school property. Joint decisions about planting and events can give both groups a meaningful role. Some areas may need to remain dedicated to pupils’ experiments, while others support community crops. Clear labels and storage arrangements help prevent accidental damage. The school also needs a plan for holidays, when pupils are absent but plants still require care. A durable agreement about these ordinary tasks is more valuable than enthusiasm at a single planting day followed by uncertainty over responsibility.',
  'digital-concerts': 'A digital audience may have opportunities that an in person listener does not, such as captions, a close view of an instrument or a later replay. These features can improve access when provided thoughtfully. They also create additional rights questions, because permission to perform live does not necessarily include unlimited recording or redistribution. Artists and venues should agree the terms beforehand. A successful stream respects those rights and makes its distinctive features useful, instead of presenting a basic camera feed as identical to attending or expecting musicians to accept exposure as sufficient payment.',
  'flexible-school-start': 'The arrangement should be reviewed after families have experienced it, not only before it begins. A timetable that looks efficient on paper may create difficult waits between siblings’ journeys or move congestion to a different junction. Schools and transport operators can collect these accounts and adjust transfer times or supervised arrival periods. Pupils’ rest also matters, particularly when an early start is proposed solely to reuse a bus. Efficiency should support education and access rather than make children carry the entire inconvenience of a cheaper transport schedule.',
  'slow-tourism': 'Longer stays may encourage relationships, but visitors still need to understand boundaries. Treating a residential street as an attraction or expecting constant access to local people can be intrusive even without a rushed itinerary. Accommodation choices and respect for ordinary routines determine how the visit is experienced by residents. Tourism providers can offer guidance and opportunities that communities actually welcome. A slower pace gives a traveller time to notice these issues, but it does not automatically produce cultural understanding unless that time is used with curiosity and consideration.',
  'flood-basement-homes': 'Information must reach tenants before a storm, particularly those whose accommodation is informal or whose first language differs from the warning. A registered building contact and clear evacuation instructions can reduce confusion, but residents need somewhere safe to go. Emergency shelters should accept necessary personal items and provide accessible transport, otherwise a person may delay leaving through fear of losing possessions or assistance. Landlords should disclose known flood risk when letting a property. This prevents the lower rent from concealing a danger that the tenant was never given a fair chance to assess.',
  'tourist-path-erosion': 'Visitors need to see that restrictions protect a particular function rather than exist mainly to inconvenience them. Signs can explain that a temporary diversion allows damaged vegetation to recover or avoids a nesting area. Guided walks may offer a fuller explanation, while local businesses can help direct customers to suitable routes. Managers should check alternative paths before promotion so the same problem is not exported. Volunteers can assist maintenance under supervision, but regular funding remains necessary; a heavily used public attraction cannot depend entirely on occasional unpaid effort after damage has accumulated.',
  'delivery-rider-safety': 'Responsibility is shared across the ordering system. Customers should receive realistic estimates and understand that a safe journey may take longer during rain or heavy traffic. Apps can avoid countdowns that frame every delay as the rider’s failure. Restaurants need space where workers can wait without blocking a pavement or leaving bicycles insecurely. A complaint process should distinguish missing food, preparation delays and transport issues. This would reduce the unfair pressure caused when several separate failures are combined into one rating that affects the rider’s future access to work.',
  'school-water-fountains': 'Schools should also consider who can physically use the equipment. A high fountain or a stiff control may be unsuitable for younger pupils or those with mobility difficulties. Refill points near activity areas reduce the need to choose between a drink and joining a game. Where tap water has an unfamiliar taste, explaining testing and allowing an adjustment period can build confidence. Families should receive reassurance without being pressured to buy branded bottles. The service works best when it becomes an ordinary, trusted part of the day, rather than a facility pupils avoid or cannot operate.',
  'elderly-heatwave': 'A register of vulnerable residents should be voluntary, secure and regularly updated. People may otherwise hesitate to share information or be overlooked after moving. A trusted local contact can confirm whether someone has a cool room, medication advice and enough drinking water, instead of merely delivering a leaflet. Housing improvements also require attention to winter needs and ventilation, since one change can affect several seasons. Planning before the summer allows landlords and services to act calmly; relying only on an emergency announcement leaves little time to help residents whose homes are already dangerously hot.',
  'electronic-waste-storage': 'Manufacturers can reduce uncertainty by providing disposal guidance when an item is sold and keeping it available afterward. A simple label directing owners to verified local services is more useful than a vague recycling symbol. Collection schemes should accept small quantities without an unreasonable fee or long journey, because those barriers encourage storage or ordinary disposal. Reporting how much equipment is repaired, reused or processed safely would strengthen confidence. It also distinguishes a genuine recovery service from a collection operation that removes devices from view while transferring the environmental risk to another community.',
  'new-workers-lonely': 'Managers should check understanding without making the employee feel constantly examined. A short discussion of what went well and where help is needed can reveal a problem before it grows. Written guidance should identify the right contact for common questions, reducing dependence on one busy colleague. Social invitations are useful but should not assume everybody can attend evening events. Integration is part of the working day, and a newcomer balancing care or long travel should not have to give up personal time merely to obtain relationships and information essential to doing the job.',
  'rural-school-teachers': 'The school’s leadership and administrative burden affect retention too. A new teacher may be attracted by a housing allowance but leave if expected to manage several subjects and extensive paperwork without help. Regional support teams can share resources, provide cover and organise specialist visits. Career advancement should recognise the complexity of remote teaching rather than require an immediate move to a city. Families benefit when experienced staff stay long enough to build trust. A retention plan therefore needs to make the job professionally credible as well as financially tolerable.',
  'polluted-school-air': 'Monitoring results should be understandable to parents and linked to action. Publishing a technical chart without explaining when outdoor activity should change leaves schools uncertain. Authorities can establish practical thresholds and provide support when repeated pollution requires adjustments. Responsibility should not fall on parents to purchase private filters or move their children elsewhere. The most exposed schools may already serve disadvantaged communities, so funding should reflect risk rather than the strength of local fundraising. This makes protection a public health duty instead of an advantage available mainly to families able to pay.',
  'renting-unpredictable': 'Information about rental rights must be accessible at the point when a household needs it. A tenant facing short notice may not have time or money for a lengthy legal dispute. Local advice services can help identify unlawful demands and negotiate a realistic transition where a move is unavoidable. Deposit procedures should be prompt and transparent, because waiting for old money can prevent securing a new home. These protections will not create housing by themselves, but they reduce the avoidable financial shocks that make each forced move more damaging than the last.',
  'tourist-litter-coast': 'Businesses can coordinate their contribution instead of relying on the council after every busy weekend. Food stalls might use common reusable containers or sponsor nearby disposal points, while hotels explain collection rules at arrival. Clean up volunteers are helpful, but their work should not substitute for the organiser or business accepting routine responsibility. The town should also track where rubbish accumulates, because a bin placed at the wrong end of a crowded beach may remain empty. Practical layout and dependable collection are more effective than a campaign whose posters are surrounded by overflowing waste.',
  'eldercare-burnout': 'Carers need a clear route to assessment before they reach exhaustion. They may regard seeking help as disloyal or believe that services are reserved for someone in a worse situation. Professionals can explain that respite protects the relationship and the continuity of care. Support should also include the older person in planning where possible, avoiding the assumption that family care removes their right to choose. A consistent substitute carer or small team can build familiarity, making a break genuinely restorative rather than another task the family must organise and worry about.',
  'digital-homework-access': 'The platform itself can create barriers even when a household has a connection. Large files, repeated logins and software available only on one type of device can consume data or fail on older equipment. Schools should test assignments under ordinary home conditions and use accessible formats. A deadline should allow time to report problems and obtain help. Teachers also need a manageable way to receive work offline, otherwise the promised alternative may be harder to use than the digital route. Equal access requires attention to these daily procedures, not just a count of devices distributed.',
  'wildfire-insurance': 'Risk information should be shared before property decisions, not only after an insurer withdraws. Buyers need to know both the physical danger and the likely cost of maintaining protection. Local planning authorities should explain why certain developments are refused, making long term public costs visible. Community improvements may reduce risk, but households should not be promised that one cleared strip guarantees safety. Independent assessment and regular review can support realistic decisions. Assistance for current residents is justified by hardship, while allowing avoidable new exposure would create future claims on the same limited support.',
  'festival-noise': 'Residents should be consulted through more than an online announcement. People working nights or living close to the site may face particular effects that a general attendance survey misses. Organisers can publish a map showing stages, exits and delivery routes, allowing practical concerns to be addressed early. Compensation or free tickets may be welcome to some, but they do not resolve lost sleep for everybody. Permission should depend on a credible operating plan, and repeated breaches should affect future approvals rather than result in a small fee treated as an ordinary event expense.',
  'online-returns-waste': 'The burden of improving the system should not be transferred wholly to shoppers. A retailer that provides inaccurate sizes or misleading photographs contributes directly to returns and should correct those practices. Recovered products can be listed with their condition clearly explained, creating a credible resale market. Customers could be shown the environmental cost of unnecessary multiple orders without being shamed for returning a genuine mismatch. Clear data on disposal and resale would also make claims verifiable. The aim is to improve decisions and recovery, not disguise a reduction in consumer rights as environmental concern.',
  'urban-public-toilets': 'Operating arrangements should suit how the area is actually used. A toilet beside an evening transport hub offers limited benefit if it closes in the late afternoon. Staffing or appropriate monitoring can address safety while preserving access. Councils should publish accurate hours and provide a prompt fault reporting route, with responsibility for resolving the issue. Facilities must also accommodate different needs, including suitable space for a carer. These details make the difference between a theoretical provision on a map and a service that lets people travel or spend time in the city with confidence.',
  'school-exam-stress': 'Teachers should discuss results privately and explain what a practice score does and does not show. A pupil may perform poorly because a topic has not yet been mastered, which calls for a plan rather than a label of low ability. Schools can coordinate major deadlines across subjects and make revision resources accessible to those without private tutoring. Support must also reach students who appear successful, since high achievement can conceal fear of maintaining expectations. Reducing stress means changing the conditions around assessment as well as offering help after a pupil has become visibly distressed.',
  'battery-fire-disposal': 'Collection points need clear arrangements for damaged batteries, which may require different handling from intact ones. A staff member should not be expected to improvise after someone arrives with a swollen phone battery. Suppliers can provide safe instructions and appropriate containers, while councils coordinate where difficult items are accepted. Guidance should avoid asking untrained residents to dismantle sealed equipment. The message becomes more credible when disposal is practical and safe at every stage, rather than simply move a hazardous object from the household bin to a poorly prepared shop counter.',
  'campus-food-cost': 'Students also need to know where support is available without repeatedly proving hardship to several departments. A single confidential route can connect food assistance, housing advice and emergency funding, since the difficulties often overlap. Meals should be available at times that suit placements and late classes rather than only during a short midday window. Institutions can consult students about cost and cultural requirements while preserving nutritious options. This avoids a scheme that is technically subsidised but unusable for the people it is intended to help, and it recognises food access as part of educational participation.',
  'late-night-sleep': 'People also need to distinguish a flexible habit from a timetable they cannot easily control. A carer waking repeatedly to assist a relative may require respite rather than a stricter bedtime. A worker rotating between early and late shifts needs recovery time built into the schedule. Advice should therefore begin by identifying why sleep is delayed and what can realistically change. When the main obstacle is entertainment, small changes to cues and planning can help. When it is employment or care, meaningful support must come from outside the individual’s evening routine.',
  'small-town-young-leave': 'Not every departure should be prevented. Study and experience elsewhere can broaden skills that later benefit the town, so a useful strategy includes maintaining connections and creating credible return routes. Local employers might offer placements or advertise opportunities to former residents without demanding an immediate move. The town also needs welcoming conditions for people who did not grow up there. Treating newcomers as less entitled to participate would weaken the same renewal the community seeks. A viable future depends on opportunities and openness, rather than preserving exactly the population and occupations of the past.',
  'takeaway-rising': 'The effects also vary with household size and equipment. A person living alone may find that ingredients sold in large packages produce waste, while a family with a well equipped kitchen can cook several portions efficiently. Ready meals from a local supplier might offer a healthier compromise than frequent fast food delivery. It is therefore more informative to examine cost, ingredients and frequency than simply divide all meals into home cooked and purchased categories. Practical cooking education and smaller ingredient packs can reduce dependence without ignoring why the convenience became attractive.',
  'language-dialect-loss': 'Preservation efforts should avoid turning dialect speakers into performers of an idealised past. Young people need freedom to discuss current interests and invent expressions, as speakers of any living language do. Older residents can contribute stories without being expected to police every change. Digital tools may support informal use through recordings or local discussion groups, although sustained face to face contact remains valuable. The aim is to keep a range of expression available, not freeze pronunciation or vocabulary so rigidly that young speakers feel they can never use the dialect correctly.',
  'delayed-parenthood': 'The consequences depend partly on the support available when a child arrives. Older parents with secure jobs may still struggle if childcare is scarce or leave arrangements are inflexible. Younger parents can provide excellent care when housing and assistance are reliable. Age should therefore not be used as a simple measure of readiness. Policies that reduce avoidable financial uncertainty can help people choose a time that suits them, while accurate health information supports realistic planning. Pressure to start a family early would not remove the conditions that caused postponement in the first place.',
  'public-bus-decline': 'Passengers also need confidence that a connection will work. A rural route arriving just after the town’s last train forces a traveller to use a car even if both services exist. Integrated planning can address these gaps without adding an entirely new network. Employers could share shift information with transport authorities, while local surveys include nonusers and their intended journeys. Comfortable shelters and accessible vehicles matter too. A service becomes credible through the whole experience from departure to arrival, not simply by offering a cheap fare on a bus that rarely fits the required trip.',
  'newspaper-local-loss': 'Funding alternatives must protect the independence that makes local reporting useful. Public support can help an underserved area, but officials should not control which investigations receive money. Reader memberships and cooperative ownership may create another route, especially when people can see the work their contributions support. Access should not disappear entirely behind payment barriers, since public decisions affect nonmembers too. A combination of dependable funding and clear editorial safeguards offers a better response than preserving a publication’s name while reducing it to press releases, promotional material and unverified community posts.',
  'children-less-outdoors': 'Access is also uneven within the same city. A family beside a well maintained park may need only encouragement, while another faces unsafe crossings and a long journey to any usable space. School grounds could provide supervised community access at suitable times, spreading opportunities without requiring every household to buy equipment. Activities should include imaginative and cooperative play, not only organised competition. This would allow children with different interests to participate and reduce the idea that being outdoors is worthwhile only when an adult is directing a formal sport.',
  'cheap-furniture-waste': 'Rental arrangements can make durable ownership difficult. A tenant who moves frequently may not know whether a large wardrobe will fit the next room, even if it is well made. Modular furniture and dependable resale or collection services address that uncertainty more directly than a campaign asking everyone to buy expensive permanent pieces. Producers can offer replaceable panels and publish assembly information that supports more than one move. The environmental benefit comes from actual continued use, so design and services should follow how households live rather than assume a stable home and unlimited storage.',
  'water-groundwater': 'Cooperation is essential because the reserve is shared beneath individual farms. A grower who conserves water may receive little benefit if nearby extraction continues unchecked, which weakens the incentive to change. Local agreements need credible monitoring and a fair way to resolve disputes. Rules should also distinguish small household or subsistence needs from large commercial demand. Information about the reserve must be understandable and regularly updated, allowing farmers to plan crops before a crisis. Waiting until wells fail makes adjustment more expensive and encourages deeper drilling that may intensify the depletion.',
  'teens-books-less': 'The distinction between format and depth should remain clear. A long book can be read mechanically, while a short article can provoke careful thought; length alone is not a measure of quality. Nevertheless, following a sustained narrative or argument develops experience that repeated brief reading may not provide. Teachers can invite discussion and choice rather than use books only as examination material. Accessible digital editions and audio support may also help some teenagers begin. Encouraging sustained engagement is more productive than treating every screen as an enemy or every printed volume as automatically valuable.',
  'food-price-volatility': 'The uncertainty itself changes behaviour before a household actually runs out of money. Families may postpone other purchases or buy large quantities when a price briefly falls, tying up savings and risking spoilage. Small food businesses face similar difficulty setting prices and planning stock. Better information about supply and targeted assistance can reduce panic, but announcements must be credible. Authorities should avoid promising permanent cheap food when the underlying costs remain unstable, instead explain which protections are available and how households can obtain them without a lengthy or humiliating process.',
  'women-engineering-barrier': 'Visibility should reflect the variety of engineering work rather than present one exceptional woman as proof that barriers have disappeared. Students could meet professionals working in water systems, software or transport and ask about ordinary career paths. Recruitment should evaluate relevant skills consistently, while promotion data can reveal whether women enter a firm but remain excluded from responsibility. These measures support informed choice and accountability. They do not require everyone to select the same field; they make it less likely that a capable person turns away because of avoidable discouragement or unfair treatment.',
  'city-noise-rise': 'Noise policy should consider timing and duration as well as volume. A short daytime event and repeated sound outside a bedroom at night can have very different effects. Residents need a practical complaint route, and authorities should identify the responsible source rather than leave households to confront it. Businesses can be given clear conditions before investing in a site. Consistent enforcement then protects both sides: residents know what is acceptable, while compliant operators are not disadvantaged by neighbours who ignore the rules and treat occasional penalties as part of their operating budget.',
  'social-media-status': 'The cycle is reinforced when a purchase becomes evidence of belonging to a group. A person may worry that reusing the same clothing or declining an expensive outing will be noticed, even if friends have never demanded it. Honest conversations can challenge these assumptions and make lower cost choices socially acceptable. Platforms and creators should also show ordinary repeated use, not only a sequence of new possessions. Financial guidance is most useful when it recognises this social pressure, because a calculation alone may not overcome the fear of exclusion that drives the spending.',
  'migrant-skills-unused': 'The process should avoid confusing language fluency with the entire professional competence of an applicant. Clear communication may be essential, but the required level varies by task and can often improve through targeted support. A supervised role can let someone demonstrate technical ability while learning local terminology. Employers also need guidance on evaluating unfamiliar experience fairly. This protects standards without requiring every newcomer to start at the lowest occupational level, which can waste skills and reduce the time available to complete the very training needed for recognition.',
  'exercise-gym-dropout': 'Enjoyment can be a stronger basis for continuity than treating activity as punishment. Someone who dislikes a crowded gym may remain active through dancing, gardening or walking with a friend. Programmes should offer ways to restart after illness or a busy period without framing the interruption as defeat. Health conditions may require professional advice, and progress can be uneven. Recognising these differences prevents a rigid plan from excluding people whose lives or bodies do not match its assumptions. Sustainable participation grows from repeated achievable experiences, not a brief period of extreme effort.',
  'rural-medical-departure': 'Local training pathways can help, but they should not assume that a rural background removes every need for support. A clinician returning home still requires equipment, leave and opportunities to develop. Teams can share duties across nearby facilities, while specialist links offer advice without forcing every patient or worker to travel long distances. Retention should be reviewed through staff experience as well as vacancy counts. A clinic that is technically staffed but depends on exhausted professionals may lose them soon and may already provide less reliable care than the figures suggest.',
  'birthdays-commercial': 'The pressure can be reduced when families agree expectations before an occasion. A shared limit on gifts or a contribution of time may make participation easier, especially where relatives have unequal incomes. Hosts can offer a simple gathering without apologising for failing to reproduce an online display. Children should also see that an enjoyable celebration can involve familiar people and thoughtful attention rather than elaborate purchases. This does not forbid an expensive event for those who choose it, but it separates voluntary enjoyment from a social obligation that makes others spend beyond their means.',
  'academic-cheating-ai': 'Rules should distinguish assistance that supports learning from substitution that conceals it. A student discussing possible structures with a tool still needs to judge the suggestions and develop the argument, whereas submitting generated paragraphs as independent work removes that responsibility. Teachers can ask learners to explain choices and identify revisions, making understanding observable. Detection scores alone should not determine punishment because they can misclassify genuine writing. Clear evidence, a chance to respond and consistent procedures preserve fairness while discouraging the belief that fluent output is equivalent to the student’s own achievement.',
};

const groups: Array<[string, Plan[]]> = [
  ['opinion', opinion],
  ['discussion', discussion],
  ['advantages', advantages],
  ['problems', problems],
  ['causes', causes],
  ['two-part', twoPart],
];

export const expandedEssayLessons: WritingEssayPack[] = groups.flatMap(([family, plans], groupIndex) =>
  plans.slice(0, 14).map((plan, index) => build(family, plan, groupIndex * 20 + index)),
);

export const expandedMockEssays: WritingEssayPack[] = groups.flatMap(([family, plans], groupIndex) =>
  plans.slice(14).map((plan, index) => build(family, plan, groupIndex * 20 + 14 + index)),
);
